                    flag: function () { if (state.finished) return; state.flags[state.idx] = !state.flags[state.idx]; byId('osc-flag-' + quizId).classList.toggle('aktif', !!state.flags[state.idx]); oscOptikGuncelle(state.idx); oscUstGuncelle(); },
                    bitir: oscBitirSor,
