                    const h = Math.floor(left / 3600), m = Math.floor((left % 3600) / 60), s = left % 60, p = function (x) { return x < 10 ? '0' + x : x; };
                    t.innerText = (h > 0 ? p(h) + ':' : '') + p(m) + ':' + p(s);
