    /* ---------------- öğretmen paneli ---------------- */
    private function ogretmen_mi() { return is_user_logged_in() && self::rol() !== 'ogrenci'; }
    private function ogr_kontrol() {
        if (!$this->ogretmen_mi()) wp_send_json_error('Oturum açmanız gerekiyor.', 403);
        check_ajax_referer('osc_sp_ogr', 'nonce');
    }
    private function benim_oturum($id) {
        $ot = $this->oturum('id', (int) $id);
        if (!$ot || ((int) $ot->ogretmen_id !== get_current_user_id() && !current_user_can('manage_options'))) wp_send_json_error('Oturum bulunamadı.');
        return $ot;
    }
    private function test_ozet($p) {
        $data = get_post_meta($p->ID, '_osc_data', true);
        $set = get_post_meta($p->ID, '_osc_settings', true);
        if (!is_array($set)) $set = array();
        $n = is_array($data) ? count($data) : 0;
        $b = self::bilgi($p->ID, $set, $n);
        $sure = (isset($set['duration']) && $set['duration'] !== '') ? (int) $set['duration'] : $b['oto_sure'];
        $cats = get_the_category($p->ID);
        return array('id' => $p->ID, 'baslik' => get_the_title($p), 'soru' => $n, 'tur' => $b['ad'], 'kural' => $b['kural'], 'sure' => $sure, 'kategori' => $cats ? $cats[0]->name : '', 'benim' => (int) $p->post_author === get_current_user_id(), 'durum' => $p->post_status);
    }
    public function ajax_ara() {
        $this->ogr_kontrol();
        $q = isset($_POST['q']) ? sanitize_text_field(wp_unslash($_POST['q'])) : '';
        $id = isset($_POST['id']) ? (int) $_POST['id'] : 0;
        $o = array();
        if ($id) {
            $p = get_post($id);
            if ($p && $p->post_type === 'osc_quiz' && ($p->post_status === 'publish' || (int) $p->post_author === get_current_user_id())) $o[] = $this->test_ozet($p);
            wp_send_json_success($o);
        }
        $args = array('post_type' => 'osc_quiz', 'post_status' => 'publish', 'posts_per_page' => 25, 'orderby' => 'date', 'order' => 'DESC');
        if ($q !== '') $args['s'] = $q;
        $benim = get_posts(array_merge($args, array('post_status' => array('publish', 'pending', 'draft'), 'author' => get_current_user_id(), 'posts_per_page' => 10)));
        $gor = array();
        foreach (array_merge($benim, get_posts($args)) as $p) { if (isset($gor[$p->ID])) continue; $gor[$p->ID] = 1; $x = $this->test_ozet($p); if ($x['soru'] > 0) $o[] = $x; }
        wp_send_json_success($o);
    }
    public function ajax_olustur() {
        $this->ogr_kontrol();
        global $wpdb;
        $qid = isset($_POST['quiz_id']) ? (int) $_POST['quiz_id'] : 0;
        $p = get_post($qid);
        if (!$p || $p->post_type !== 'osc_quiz' || !($p->post_status === 'publish' || (int) $p->post_author === get_current_user_id())) wp_send_json_error('Test bulunamadı.');
        $data = get_post_meta($qid, '_osc_data', true);
        if (!is_array($data) || !$data) wp_send_json_error('Bu testte soru yok.');
        $set = get_post_meta($qid, '_osc_settings', true); if (!is_array($set)) $set = array();
        $b = self::bilgi($qid, $set, count($data));
        $tur = (isset($_POST['tur']) && $_POST['tur'] === 'odev') ? 'odev' : 'canli';
        $sure = max(0, min(600, isset($_POST['sure']) ? (int) $_POST['sure'] : 0));
        $son = 0;
        if ($tur === 'odev') {
            $st = isset($_POST['son_tarih']) ? sanitize_text_field(wp_unslash($_POST['son_tarih'])) : '';
            try { $dt = new DateTime($st, wp_timezone()); $son = $dt->getTimestamp(); } catch (Exception $e) { $son = 0; }
            if ($son && $son < time() + 300) wp_send_json_error('Son teslim tarihi ileri bir zaman olmalı.');
        }
        $baslik = isset($_POST['baslik']) ? sanitize_text_field(wp_unslash($_POST['baslik'])) : '';
        if ($baslik === '') $baslik = get_the_title($qid);
        $ayar = array('sonuc_goster' => (isset($_POST['sonuc_goster']) && $_POST['sonuc_goster'] === 'hemen') ? 'hemen' : 'bitince', 'kural' => $b['kural'], 'tur_ad' => $b['ad']);
        $kod = $this->yeni_kod();
        $ok = $wpdb->insert($this->t_ot(), array('kod' => $kod, 'quiz_id' => $qid, 'ogretmen_id' => get_current_user_id(), 'tur' => $tur, 'baslik' => function_exists('mb_substr') ? mb_substr($baslik, 0, 190) : substr($baslik, 0, 190), 'durum' => $tur === 'odev' ? 'basladi' : 'bekliyor', 'sure' => $sure, 'baslangic' => $tur === 'odev' ? time() : 0, 'son_tarih' => $son, 'ayar' => wp_json_encode($ayar), 'veri' => wp_json_encode(array_values($data)), 'olusturma' => time()));
        if (!$ok) wp_send_json_error('Oturum oluşturulamadı: ' . $wpdb->last_error);
        wp_send_json_success(array('id' => (int) $wpdb->insert_id, 'kod' => $kod));
    }
    public function ajax_oturumlar() {
        $this->ogr_kontrol();
        global $wpdb;
        $rows = $wpdb->get_results($wpdb->prepare("SELECT o.id, o.kod, o.quiz_id, o.tur, o.baslik, o.durum, o.sure, o.bitis, o.son_tarih, o.olusturma, (SELECT COUNT(*) FROM {$this->t_kt()} k WHERE k.oturum_id = o.id) AS katilan, (SELECT COUNT(*) FROM {$this->t_kt()} k WHERE k.oturum_id = o.id AND k.durum = 'bitti') AS biten, (SELECT AVG(k.net) FROM {$this->t_kt()} k WHERE k.oturum_id = o.id AND k.durum = 'bitti') AS ort FROM {$this->t_ot()} o WHERE o.ogretmen_id = %d ORDER BY o.id DESC LIMIT 100", get_current_user_id()));
        $o = array();
        foreach ($rows as $r) {
            $r->durum = $this->etkin_durum($r);
            $o[] = array('id' => (int) $r->id, 'kod' => $r->kod, 'tur' => $r->tur, 'baslik' => $r->baslik, 'test' => get_the_title($r->quiz_id), 'durum' => $r->durum, 'katilan' => (int) $r->katilan, 'biten' => (int) $r->biten, 'ort' => $r->ort !== null ? round((float) $r->ort, 2) : null, 'tarih' => $this->tarih($r->olusturma), 'son_tarih' => $this->tarih($r->son_tarih));
        }
        wp_send_json_success($o);
    }
    public function ajax_izle() {
        $this->ogr_kontrol();
        global $wpdb;
        $ot = $this->benim_oturum(isset($_POST['id']) ? $_POST['id'] : 0);
        $d = $this->etkin_durum($ot);
        $veri = $this->veri($ot);
        $kts = $wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t_kt()} WHERE oturum_id = %d ORDER BY id ASC", $ot->id));
        $now = time();
        $liste = array();
        foreach ($kts as $kt) {
            // oturum bittiği halde teslim etmeyenleri son kaydedilen cevaplarla değerlendir
            $kapandi = $d === 'bitti' && (($ot->tur === 'canli' && $now > (int) $ot->bitis + 30) || ($ot->tur === 'odev') || ($ot->tur === 'canli' && !$ot->bitis));
            if ($kt->durum === 'cozuyor' && ($kapandi || ($ot->tur === 'odev' && $kt->bitis && $now > $kt->bitis + 150))) {
                $cev = json_decode((string) $kt->cevaplar, true);
                $this->bitir_katilimci($ot, $kt, $this->cevap_dizisi(wp_json_encode(is_array($cev) ? $cev : array()), count($veri)));
                $kt = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t_kt()} WHERE id = %d", $kt->id));
            }
            $s = json_decode((string) $kt->sonuc, true);
            $cev = json_decode((string) $kt->cevaplar, true);
            $liste[] = array('id' => (int) $kt->id, 'ad' => $kt->ad, 'durum' => $kt->durum, 'ilerleme' => (int) $kt->ilerleme, 'cevrimici' => ($now - (int) $kt->son) < 25, 'd' => (float) $kt->dogru, 'y' => (float) $kt->yanlis, 'b' => (int) $kt->bos, 'net' => (float) $kt->net, 'puan' => (int) $kt->puan, 'sure' => ($kt->durum === 'bitti' && $kt->baslama) ? max(0, (int) $kt->bitis - (int) $kt->baslama) : 0, 'durumlar' => is_array($s) && isset($s['durum']) ? $s['durum'] : null, 'cevaplar' => !empty($_POST['rapor']) && is_array($cev) ? $cev : null);
        }
        $cevap = array(
            'id' => (int) $ot->id, 'kod' => $ot->kod, 'tur' => $ot->tur, 'baslik' => $ot->baslik, 'test' => get_the_title($ot->quiz_id), 'durum' => $d,
            'sure' => (int) $ot->sure, 'kalan' => $this->kalan($ot, null), 'son_tarih' => $this->tarih($ot->son_tarih), 'link' => self::ogrenci_url($ot->kod),
            'katil_link' => ($pid = (int) get_option('osc_sp_katil_sayfa')) ? get_permalink($pid) : home_url('/?osc_k='), 'soru' => count($veri), 'kural' => $this->kural($ot), 'ayar' => $this->ayar($ot), 'katilimcilar' => $liste,
        );
        if (!empty($_POST['rapor'])) {
            $sorular = array();
            foreach ($veri as $q) {
                $t = isset($q['type']) ? $q['type'] : 'multiple';
                $kok = trim(preg_replace('/\s+/', ' ', wp_strip_all_tags(html_entity_decode((isset($q['root']) ? $q['root'] : '') . '', ENT_QUOTES, 'UTF-8'))));
                $sorular[] = array('tur' => $t, 'kok' => function_exists('mb_substr') ? mb_substr($kok, 0, 140) : substr($kok, 0, 140), 'konu' => isset($q['konu']) ? (string) $q['konu'] : '', 'dogru' => ($t === 'gap' || $t === 'classic') ? wp_strip_all_tags(isset($q['options']['A']) ? $q['options']['A'] : '') : (isset($q['correct']) ? $q['correct'] : ''), 'secenekler' => $t === 'truefalse' ? array('A', 'B') : ($t === 'multiple' ? array_values(array_filter(array('A', 'B', 'C', 'D', 'E'), function ($k) use ($q) { return !empty($q['options'][$k]); })) : array()));
            }
            $cevap['sorular'] = $sorular;
        }
        wp_send_json_success($cevap);
    }
    public function ajax_komut() {
        $this->ogr_kontrol();
        global $wpdb;
        $ot = $this->benim_oturum(isset($_POST['id']) ? $_POST['id'] : 0);
        $islem = isset($_POST['islem']) ? sanitize_key($_POST['islem']) : '';
        $now = time();
        switch ($islem) {
            case 'baslat':
                if ($ot->tur !== 'canli' || $ot->durum !== 'bekliyor') wp_send_json_error('Oturum zaten başlamış.');
                $wpdb->update($this->t_ot(), array('durum' => 'basladi', 'baslangic' => $now, 'bitis' => $ot->sure > 0 ? $now + $ot->sure * 60 : 0), array('id' => $ot->id));
                $wpdb->query($wpdb->prepare("UPDATE {$this->t_kt()} SET durum = 'cozuyor', baslama = %d WHERE oturum_id = %d AND durum = 'bekliyor'", $now, $ot->id));
                break;
            case 'sure_ekle':
                $dk = max(1, min($ot->tur === 'odev' ? 10080 : 60, isset($_POST['dk']) ? (int) $_POST['dk'] : 5));
                if ($ot->tur === 'canli' && $ot->bitis) $wpdb->update($this->t_ot(), array('bitis' => max($now, (int) $ot->bitis) + $dk * 60, 'durum' => 'basladi'), array('id' => $ot->id));
                elseif ($ot->tur === 'odev' && $ot->son_tarih) $wpdb->update($this->t_ot(), array('son_tarih' => max($now, (int) $ot->son_tarih) + $dk * 60, 'durum' => 'basladi'), array('id' => $ot->id));
                break;
            case 'bitir':
                $wpdb->update($this->t_ot(), array('durum' => 'bitti', 'bitis' => $now), array('id' => $ot->id));
                break;
            case 'sil':
                $wpdb->delete($this->t_kt(), array('oturum_id' => $ot->id));
                $wpdb->delete($this->t_ot(), array('id' => $ot->id));
                break;
            case 'katilimci_sil':
                $wpdb->delete($this->t_kt(), array('id' => isset($_POST['kid']) ? (int) $_POST['kid'] : 0, 'oturum_id' => $ot->id));
                break;
            default: wp_send_json_error('Geçersiz işlem.');
        }
        wp_send_json_success(array('ok' => true));
    }

    /* ---------------- öğretmen testleri ---------------- */
    private function izinli_html() {
        $a = array('class' => true, 'style' => true);
        return array('b' => array(), 'strong' => array(), 'i' => array(), 'em' => array(), 'u' => array(), 'br' => array(), 'p' => $a, 'sub' => array(), 'sup' => array(), 'span' => $a, 'div' => $a,
            'img' => array('src' => true, 'alt' => true, 'width' => true, 'height' => true, 'style' => true, 'class' => true), 'table' => $a, 'tbody' => array(), 'thead' => array(), 'tr' => array(), 'td' => array('colspan' => true, 'rowspan' => true, 'style' => true), 'th' => array('colspan' => true, 'rowspan' => true, 'style' => true), 'ul' => array(), 'ol' => array(), 'li' => array());
    }
    private function temiz($s) { return trim(wp_kses((string) $s, $this->izinli_html())); }
    public function ajax_testlerim() {
        $this->ogr_kontrol();
        $ps = get_posts(array('post_type' => 'osc_quiz', 'post_status' => array('publish', 'pending', 'draft'), 'author' => get_current_user_id(), 'posts_per_page' => 200, 'orderby' => 'modified', 'order' => 'DESC'));
        $o = array();
        foreach ($ps as $p) {
            $x = $this->test_ozet($p);
            $x['red'] = (string) get_post_meta($p->ID, '_osc_red_notu', true);
            $x['tarih'] = get_the_modified_date('d.m.Y H:i', $p);
            $yz = (int) get_post_meta($p->ID, '_osc_yazi_id', true);
            $x['link'] = ($yz && get_post_status($yz) === 'publish') ? get_permalink($yz) : '';
            $o[] = $x;
        }
        wp_send_json_success($o);
    }
    public function ajax_test_al() {
        $this->ogr_kontrol();
        $p = get_post(isset($_POST['id']) ? (int) $_POST['id'] : 0);
        if (!$p || $p->post_type !== 'osc_quiz' || ((int) $p->post_author !== get_current_user_id() && $p->post_status !== 'publish')) wp_send_json_error('Test bulunamadı.');
        $set = get_post_meta($p->ID, '_osc_settings', true); if (!is_array($set)) $set = array();
        $cats = wp_get_post_categories($p->ID);
        wp_send_json_success(array('id' => (int) $p->post_author === get_current_user_id() && $p->post_status !== 'publish' ? $p->ID : 0, 'baslik' => $p->post_title, 'aciklama' => $p->post_excerpt, 'kategori' => $cats ? (int) $cats[0] : 0, 'sinav_turu' => isset($set['sinav_turu']) ? $set['sinav_turu'] : '', 'sure' => isset($set['duration']) ? $set['duration'] : '', 'sorular' => get_post_meta($p->ID, '_osc_data', true) ?: array(), 'durum' => $p->post_status));
    }
    public function ajax_test_kaydet() {
        $this->ogr_kontrol();
        $id = isset($_POST['id']) ? (int) $_POST['id'] : 0;
        if ($id) {
            $p = get_post($id);
            if (!$p || $p->post_type !== 'osc_quiz' || (int) $p->post_author !== get_current_user_id()) wp_send_json_error('Test bulunamadı.');
            if ($p->post_status === 'publish') wp_send_json_error('Yayındaki test değiştirilemez. “Kopyala” ile yeni bir sürüm oluşturabilirsiniz.');
        }
        $baslik = isset($_POST['baslik']) ? sanitize_text_field(wp_unslash($_POST['baslik'])) : '';
        if ((function_exists('mb_strlen') ? mb_strlen($baslik) : strlen($baslik)) < 5) wp_send_json_error('Test başlığı en az 5 karakter olmalı.');
        $ham = json_decode(wp_unslash(isset($_POST['sorular']) ? $_POST['sorular'] : '[]'), true);
        if (!is_array($ham) || !$ham) wp_send_json_error('En az bir soru ekleyin.');
        if (count($ham) > 200) wp_send_json_error('Bir testte en fazla 200 soru olabilir.');
        $sorular = array();
        foreach ($ham as $i => $q) {
            $t = isset($q['type']) && in_array($q['type'], array('multiple', 'truefalse', 'gap', 'classic'), true) ? $q['type'] : 'multiple';
            $o = array('type' => $t, 'konu' => sanitize_text_field(isset($q['konu']) ? $q['konu'] : ''), 'paragraph' => $this->temiz(isset($q['paragraph']) ? $q['paragraph'] : ''), 'root' => $this->temiz(isset($q['root']) ? $q['root'] : ''), 'options' => array(), 'correct' => 'A');
            if ($o['root'] === '' && $o['paragraph'] === '') wp_send_json_error(($i + 1) . '. sorunun metni boş.');
            if ($t === 'truefalse') { $o['options'] = array('A' => 'Doğru', 'B' => 'Yanlış'); $o['correct'] = (isset($q['correct']) && $q['correct'] === 'B') ? 'B' : 'A'; }
            elseif ($t === 'gap' || $t === 'classic') { $o['options'] = array('A' => $this->temiz(isset($q['options']['A']) ? $q['options']['A'] : '')); if ($t === 'gap' && $o['options']['A'] === '') wp_send_json_error(($i + 1) . '. sorunun doğru cevabını yazın.'); }
            else {
                $dolu = 0;
                foreach (array('A', 'B', 'C', 'D', 'E') as $k) { $v = $this->temiz(isset($q['options'][$k]) ? $q['options'][$k] : ''); $o['options'][$k] = $v; if ($v !== '') $dolu++; }
                if ($dolu < 2) wp_send_json_error(($i + 1) . '. soruda en az iki şık olmalı.');
                $c = isset($q['correct']) ? strtoupper((string) $q['correct']) : '';
                if (!isset($o['options'][$c]) || $o['options'][$c] === '') wp_send_json_error(($i + 1) . '. sorunun doğru şıkkını işaretleyin.');
                $o['correct'] = $c;
            }
            $sorular[] = $o;
        }
        $gonder = !empty($_POST['gonder']);
        $tur = isset($_POST['sinav_turu']) && array_key_exists($_POST['sinav_turu'], self::turler()) ? sanitize_key($_POST['sinav_turu']) : '';
        $sure = isset($_POST['sure']) && $_POST['sure'] !== '' ? (string) max(0, min(600, (int) $_POST['sure'])) : '';
        $arr = array('post_type' => 'osc_quiz', 'post_title' => $baslik, 'post_excerpt' => sanitize_textarea_field(wp_unslash(isset($_POST['aciklama']) ? $_POST['aciklama'] : '')), 'post_status' => $gonder ? 'pending' : 'draft', 'post_author' => get_current_user_id());
        if ($id) { $arr['ID'] = $id; $id = wp_update_post($arr, true); } else $id = wp_insert_post($arr, true);
        if (is_wp_error($id)) wp_send_json_error($id->get_error_message());
        update_post_meta($id, '_osc_data', $sorular);
        update_post_meta($id, '_osc_settings', array('duration' => $sure, 'view_mode' => 'step', 'sinav_turu' => $tur, 'ad_freq' => '', 'ad_code' => ''));
        update_post_meta($id, '_osc_ogretmen', 1);
        delete_post_meta($id, '_osc_red_notu');
        $kat = isset($_POST['kategori']) ? (int) $_POST['kategori'] : 0;
        if ($kat && term_exists($kat, 'category')) wp_set_post_categories($id, array($kat));
        if ($gonder) {
            $u = wp_get_current_user();
            wp_mail(get_option('admin_email'), '[' . get_bloginfo('name') . '] Onay bekleyen yeni öğretmen testi', $u->display_name . ' (' . $u->user_email . ") yeni bir test gönderdi:\n\n" . $baslik . ' — ' . count($sorular) . " soru\n\nİncelemek ve onaylamak için:\n" . admin_url('post.php?post=' . $id . '&action=edit') . "\n\nOnay bekleyen tüm testler:\n" . admin_url('edit.php?post_type=osc_quiz&post_status=pending'));
        }
        wp_send_json_success(array('id' => $id, 'durum' => $gonder ? 'pending' : 'draft'));
    }
    public function ajax_test_sil() {
        $this->ogr_kontrol();
        $p = get_post(isset($_POST['id']) ? (int) $_POST['id'] : 0);
        if (!$p || $p->post_type !== 'osc_quiz' || (int) $p->post_author !== get_current_user_id() || $p->post_status === 'publish') wp_send_json_error('Bu test silinemez.');
        wp_trash_post($p->ID);
        wp_send_json_success(array('ok' => true));
    }
    public function ajax_gorsel() {
        $this->ogr_kontrol();
        $uid = get_current_user_id();
        $say = (int) get_transient('osc_sp_gorsel_' . $uid);
        if ($say > 80) wp_send_json_error('Saatlik görsel yükleme sınırına ulaştınız.');
        $data = isset($_POST['data']) ? wp_unslash($_POST['data']) : '';
        if (!preg_match('#^data:image/(png|jpe?g|gif|webp);base64,#i', $data)) wp_send_json_error('Geçersiz resim.');
        $bin = base64_decode(substr($data, strpos($data, ',') + 1), true);
        if ($bin === false || strlen($bin) < 20 || strlen($bin) > 3 * 1024 * 1024) wp_send_json_error('Resim en fazla 3 MB olabilir.');
        $info = function_exists('getimagesizefromstring') ? @getimagesizefromstring($bin) : false;
        $ext = array('image/png' => 'png', 'image/jpeg' => 'jpg', 'image/gif' => 'gif', 'image/webp' => 'webp');
        if (!$info || empty($info['mime']) || !isset($ext[$info['mime']])) wp_send_json_error('Dosya bir resim değil.');
        $up = wp_upload_bits('ogretmen-soru-' . $uid . '-' . wp_generate_password(8, false, false) . '.' . $ext[$info['mime']], null, $bin);
        if (!empty($up['error'])) wp_send_json_error($up['error']);
        $att = wp_insert_attachment(array('post_mime_type' => $info['mime'], 'post_title' => 'Öğretmen soru görseli', 'post_content' => '', 'post_status' => 'inherit', 'post_author' => $uid), $up['file']);
        if ($att && !is_wp_error($att)) { require_once ABSPATH . 'wp-admin/includes/image.php'; wp_update_attachment_metadata($att, wp_generate_attachment_metadata($att, $up['file'])); }
        set_transient('osc_sp_gorsel_' . $uid, $say + 1, HOUR_IN_SECONDS);
        wp_send_json_success(array('url' => $up['url']));
    }

    /* ---------------- yönetici onayı ---------------- */
    public function yayin_gecisi($yeni, $eski, $post) {
        if ($post->post_type !== 'osc_quiz' || $yeni !== 'publish' || $eski === 'publish' || !get_post_meta($post->ID, '_osc_ogretmen', true)) return;
        delete_post_meta($post->ID, '_osc_red_notu');
        $yz = (int) get_post_meta($post->ID, '_osc_yazi_id', true);
        $u = get_userdata($post->post_author);
        if (!$yz || !get_post($yz)) {
            $icerik = ($post->post_excerpt ? '<p>' . esc_html($post->post_excerpt) . '</p>' . "\n\n" : '') . '[osc_quiz id="' . $post->ID . '"]' . "\n\n" . ($u ? '<p class="osc-hazirlayan">Bu test öğretmenimiz <strong>' . esc_html($u->display_name) . '</strong> tarafından hazırlanmıştır.</p>' : '');
            $yz = wp_insert_post(array('post_type' => 'post', 'post_status' => 'publish', 'post_title' => $post->post_title, 'post_content' => $icerik, 'post_author' => $post->post_author, 'post_category' => wp_get_post_categories($post->ID)));
            if ($yz && !is_wp_error($yz)) { update_post_meta($post->ID, '_osc_yazi_id', $yz); $th = get_post_thumbnail_id($post->ID); if ($th) set_post_thumbnail($yz, $th); }
        }
        if ($u && $u->user_email) wp_mail($u->user_email, '[' . get_bloginfo('name') . '] Testiniz yayınlandı 🎉', 'Merhaba ' . $u->display_name . ",\n\n“" . $post->post_title . "” testiniz onaylandı ve yayınlandı.\n\n" . ($yz && !is_wp_error($yz) ? get_permalink($yz) . "\n\n" : '') . "Teşekkür ederiz!");
    }
    public function admin_onay() {
        $id = isset($_GET['id']) ? (int) $_GET['id'] : 0;
        if (!current_user_can('publish_post', $id) || !wp_verify_nonce(isset($_GET['_wpnonce']) ? $_GET['_wpnonce'] : '', 'osc_sp_onay_' . $id)) wp_die('Yetkiniz yok.');
        wp_update_post(array('ID' => $id, 'post_status' => 'publish'));
        wp_safe_redirect(admin_url('edit.php?post_type=osc_quiz&osc_sp=onay')); exit;
    }
    public function admin_red() {
        $id = isset($_GET['id']) ? (int) $_GET['id'] : 0;
        if (!current_user_can('edit_post', $id) || !wp_verify_nonce(isset($_GET['_wpnonce']) ? $_GET['_wpnonce'] : '', 'osc_sp_red_' . $id)) wp_die('Yetkiniz yok.');
        $not = isset($_GET['not']) ? sanitize_textarea_field(wp_unslash($_GET['not'])) : '';
        wp_update_post(array('ID' => $id, 'post_status' => 'draft'));
        update_post_meta($id, '_osc_red_notu', $not ? $not : 'Test yayın kurallarına uygun bulunmadı.');
        $p = get_post($id); $u = $p ? get_userdata($p->post_author) : null;
        if ($u && $u->user_email) wp_mail($u->user_email, '[' . get_bloginfo('name') . '] Testiniz için düzeltme gerekiyor', 'Merhaba ' . $u->display_name . ",\n\n“" . $p->post_title . "” testiniz şu an yayınlanamadı.\n\nNot: " . get_post_meta($id, '_osc_red_notu', true) . "\n\nDüzeltip yeniden göndermek için öğretmen paneline girebilirsiniz:\n" . self::panel_url());
        wp_safe_redirect(admin_url('edit.php?post_type=osc_quiz&osc_sp=red')); exit;
    }
    public function satir_eylemleri($a, $post) {
        if ($post->post_type !== 'osc_quiz' || !get_post_meta($post->ID, '_osc_ogretmen', true) || $post->post_status === 'publish') return $a;
        if (current_user_can('publish_post', $post->ID)) {
            $a = array('osc_onay' => '<a style="color:#008a20;font-weight:600" href="' . esc_url(wp_nonce_url(admin_url('admin-post.php?action=osc_sp_onay&id=' . $post->ID), 'osc_sp_onay_' . $post->ID)) . '">✔ Onayla ve yayınla</a>', 'osc_red' => '<a style="color:#b32d2e" href="#" onclick="var n=prompt(\'Öğretmene iletilecek düzeltme notu:\');if(n!==null){location.href=\'' . esc_js(wp_nonce_url(admin_url('admin-post.php?action=osc_sp_red&id=' . $post->ID), 'osc_sp_red_' . $post->ID)) . '&not=\'+encodeURIComponent(n);}return false;">✖ Reddet</a>') + $a;
        }
        return $a;
    }
    public function sutun_ekle($c) { $c['osc_gonderen'] = 'Gönderen'; return $c; }
    public function sutun_goster($col, $id) {
        if ($col !== 'osc_gonderen') return;
        if (!get_post_meta($id, '_osc_ogretmen', true)) { echo '<span style="color:#999">Yönetici</span>'; return; }
        $p = get_post($id); $u = get_userdata($p->post_author);
        $st = array('pending' => '<span style="background:#fff3cd;color:#8a6100;padding:2px 8px;border-radius:10px;font-weight:600">Onay bekliyor</span>', 'draft' => get_post_meta($id, '_osc_red_notu', true) ? '<span style="background:#fde7e5;color:#b42318;padding:2px 8px;border-radius:10px">Reddedildi</span>' : '<span style="color:#666">Taslak</span>', 'publish' => '<span style="background:#ddf4e8;color:#0f7b4b;padding:2px 8px;border-radius:10px">Yayında</span>');
        echo '👩‍🏫 ' . esc_html($u ? $u->display_name : '?') . '<br>' . (isset($st[$p->post_status]) ? $st[$p->post_status] : esc_html($p->post_status));
    }
    private function bekleyen_say() {
        $q = new WP_Query(array('post_type' => 'osc_quiz', 'post_status' => 'pending', 'meta_key' => '_osc_ogretmen', 'posts_per_page' => 1, 'fields' => 'ids'));
        return (int) $q->found_posts;
    }
    public function menu_rozet() {
        global $menu;
        if (!current_user_can('edit_others_posts') || !is_array($menu)) return;
        $n = $this->bekleyen_say();
        if (!$n) return;
        foreach ($menu as $k => $m) if (isset($m[2]) && $m[2] === 'edit.php?post_type=osc_quiz') $menu[$k][0] .= ' <span class="awaiting-mod"><span class="pending-count">' . $n . '</span></span>';
    }
    public function admin_bildirim() {
        if (!current_user_can('edit_others_posts')) return;
        $sc = function_exists('get_current_screen') ? get_current_screen() : null;
        if (!$sc || $sc->post_type !== 'osc_quiz') return;
        if (isset($_GET['osc_sp'])) echo '<div class="notice notice-success is-dismissible"><p>' . ($_GET['osc_sp'] === 'onay' ? 'Test onaylandı; sitede yayın yazısı oluşturuldu ve öğretmene e-posta gönderildi.' : 'Test reddedildi ve öğretmene not iletildi.') . '</p></div>';
        $n = $this->bekleyen_say();
        if ($n && $sc->base === 'edit') echo '<div class="notice notice-warning"><p><strong>' . $n . ' öğretmen testi onay bekliyor.</strong> <a href="' . esc_url(admin_url('edit.php?post_type=osc_quiz&post_status=pending')) . '">Onay bekleyenleri göster</a> · Satırdaki “Onayla ve yayınla” testi yayınlar ve sitede otomatik bir yazı oluşturur.</p></div>';
    }

    /* ---------------- panel kısa kodu ---------------- */
    public function panel_kisa_kod() {
        if (!$this->ogretmen_mi()) {
            $uu = self::sayfa_url('osc_sp_uye_sayfa', array('git' => get_permalink(), 'rol' => 'ogretmen'));
            $og = is_user_logged_in();
            return '<div class="osc-uy-kucuk">' . self::logo(34) . '<div class="ik">👩‍🏫</div><h2>Öğretmen Paneli</h2><p>' . ($og ? 'Bu sayfa öğretmen hesapları içindir. Öğrenci hesabıyla giriş yaptınız.' : 'Canlı sınıf sınavı başlatmak, ödev linki göndermek ve test eklemek için öğretmen hesabınızla giriş yapın.') . '</p>' . ($og ? '<a class="osc-uy-btn" href="' . esc_url(self::sayfa_url('osc_sp_ogrenci_sayfa')) . '">Öğrenci paneline git</a>' : ($uu ? '<a class="osc-uy-btn" href="' . esc_url($uu) . '">Giriş yap / Öğretmen olarak kaydol</a>' : '<a class="osc-uy-btn" href="' . esc_url(wp_login_url(get_permalink())) . '">Giriş yap</a>')) . '</div>' . $this->uy_kucuk_css();
        }
        $u = wp_get_current_user();
        $kat = array();
        $ekle = function ($parent, $d) use (&$ekle, &$kat) { foreach (get_categories(array('hide_empty' => false, 'parent' => $parent, 'orderby' => 'name')) as $c) { $kat[] = array('id' => $c->term_id, 'ad' => str_repeat('— ', $d) . $c->name); $ekle($c->term_id, $d + 1); } };
        $ekle(0, 0);
        $turler = array(); foreach (self::turler() as $k => $t) $turler[] = array('k' => $k, 'ad' => $t['ad'], 'kural' => $t['kural'], 'dk' => $t['dk']);
        $cfg = array('ajax' => admin_url('admin-ajax.php'), 'nonce' => wp_create_nonce('osc_sp_ogr'), 'ad' => $u->display_name, 'kategoriler' => $kat, 'turler' => $turler, 'yeni' => isset($_GET['yeni']) ? (int) $_GET['yeni'] : 0, 'cikis' => wp_logout_url(), 'site' => get_bloginfo('name'), 'lib' => add_query_arg('osc_import_lib', '22', home_url('/')), 'logo' => self::logo_src(), 'home' => home_url('/'), 'ogrenci' => self::sayfa_url('osc_sp_ogrenci_sayfa'), 'yazili' => class_exists('OSC_Yazili') && OSC_Yazili::gorebilir() ? self::sayfa_url('osc_yz_sayfa') : '', 'yz' => class_exists('OSC_Yazili') && OSC_Yazili::gorebilir() ? OSC_Yazili::cfg(true) : null, 'yz_js' => class_exists('OSC_Yazili') ? OSC_Yazili::kaynak_url('js') : '', 'yz_css' => class_exists('OSC_Yazili') ? OSC_Yazili::kaynak_url('css') : '');
        ob_start(); ?>
<div id="osc-pn" class="osc-pn"><div class="osc-pn-yukleniyor">Yükleniyor…</div></div>
<style>.osc-pn{--i:#4f46e5;--id:#4338ca;--k:#0f172a;--k2:#475569;--s:#64748b;--c:#e5e7eb;--z:#f6f7fb;font-family:inherit;color:var(--k);max-width:1180px;margin:0 auto 40px;box-sizing:border-box}
.osc-pn *,.osc-pn *::before,.osc-pn *::after{box-sizing:border-box}
.osc-pn a{text-decoration:none}
.osc-pn-yukleniyor{padding:40px;text-align:center;color:var(--s)}
.osc-pn-ust{display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:var(--k);color:#fff;border-radius:20px;padding:14px 18px;margin-bottom:18px}
.osc-pn-marka{display:flex;align-items:center;gap:10px}
.osc-pn-marka .ik{width:42px;height:42px;border-radius:12px;background:rgba(255,255,255,.12);display:flex;align-items:center;justify-content:center;font-size:22px}
.osc-pn-marka b{display:block;font-size:16px}.osc-pn-marka small{color:#a5b4fc;font-size:12px}
.osc-pn-sek{display:flex;gap:4px;background:rgba(255,255,255,.08);border-radius:12px;padding:4px;margin-left:auto}
.osc-pn-sek a{color:#cbd5e1;padding:8px 14px;border-radius:9px;font-weight:700;font-size:14px}
.osc-pn-sek a.on{background:#fff;color:var(--k)}
.osc-pn-kim{font-size:13px;color:#cbd5e1}.osc-pn-kim a{color:#a5b4fc}
.osc-pn-h2{font-size:22px;margin:22px 0 12px;font-weight:800}
.osc-pn-not{color:var(--s);font-size:13.5px;margin:4px 0 12px}
.osc-pn-geri{display:inline-block;color:var(--s);font-weight:700;font-size:14px;margin:4px 0 6px}
.osc-pn-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;background:#fff;border:1.5px solid var(--c);color:var(--k);border-radius:11px;padding:9px 14px;font-weight:700;font-size:14px;cursor:pointer;font-family:inherit;line-height:1.2;text-decoration:none}
.osc-pn-btn:hover{border-color:#94a3b8}
.osc-pn-btn:disabled{opacity:.5;cursor:default}
.osc-pn-btn.ana{background:var(--i);border-color:var(--i);color:#fff}.osc-pn-btn.ana:hover{background:var(--id)}
.osc-pn-btn.kirmizi{background:#dc2626;border-color:#dc2626;color:#fff}
.osc-pn-btn.kirmizi-y{color:#dc2626}
.osc-pn-btn.buyuk{padding:15px 22px;font-size:16px;border-radius:14px;width:100%}
.osc-pn-btns{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
.osc-pn-cta{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.osc-pn-cta-k{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1.5px solid var(--c);border-radius:20px;padding:20px;color:var(--k);transition:.15s}
.osc-pn-cta-k:hover{transform:translateY(-2px);box-shadow:0 14px 30px -18px rgba(15,23,42,.4)}
.osc-pn-cta-k.canli{border-color:#fecaca;background:linear-gradient(135deg,#fff,#fff5f5)}
.osc-pn-cta-k.odev{border-color:#c7d2fe;background:linear-gradient(135deg,#fff,#f5f7ff)}
.osc-pn-cta-k span{font-size:30px}.osc-pn-cta-k b{display:block;font-size:17px;margin-bottom:4px}.osc-pn-cta-k small{color:var(--k2);font-size:13.5px;line-height:1.45}
.osc-pn-liste{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:12px}
.osc-pn-ok{display:flex;flex-direction:column;gap:4px;background:#fff;border:1px solid var(--c);border-radius:16px;padding:14px 16px;color:var(--k);transition:.15s}
a.osc-pn-ok:hover{border-color:#a5b4fc;box-shadow:0 10px 24px -16px rgba(79,70,229,.6)}
.osc-pn-ok .ust{display:flex;gap:6px;align-items:center;margin-bottom:4px}
.osc-pn-ok .kod{margin-left:auto;font-family:ui-monospace,Menlo,monospace;font-weight:800;letter-spacing:.08em;color:var(--i)}
.osc-pn-ok b{font-size:15.5px}.osc-pn-ok small{color:var(--s);font-size:12.5px}
.osc-pn-ok .alt{display:flex;gap:10px;flex-wrap:wrap;font-size:12.5px;color:var(--k2);margin-top:6px}
.osc-pn-ok .tarih{margin-left:auto;font-size:12px}
.osc-pn-ok .red{background:#fef2f2;color:#991b1b;border-radius:10px;padding:8px 10px;font-size:13px;margin-top:6px}
.osc-pn-ok .eylem{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}
.osc-pn-ok .eylem .osc-pn-btn{padding:7px 10px;font-size:13px}
.tur{font-size:11px;font-weight:800;padding:3px 8px;border-radius:999px;text-transform:uppercase;letter-spacing:.04em}
.tur.canli{background:#fee2e2;color:#b91c1c}.tur.odev{background:#e0e7ff;color:#3730a3}
.cip{font-size:11.5px;font-weight:700;padding:3px 9px;border-radius:999px;background:#f1f5f9;color:#475569}
.cip.yesil{background:#dcfce7;color:#166534}.cip.koyu{background:#1e293b;color:#fff}.cip.sari{background:#fef3c7;color:#92400e}.cip.kirmizi{background:#fee2e2;color:#991b1b}
.osc-pn-bos{grid-column:1/-1;background:#fff;border:1.5px dashed #cbd5e1;border-radius:16px;padding:26px;text-align:center;color:var(--s);line-height:1.6}
.osc-pn-bos.big{padding:40px}
.osc-pn-bos a{color:var(--i);font-weight:700}
.osc-pn-kart{background:#fff;border:1px solid var(--c);border-radius:20px;padding:20px;margin-bottom:14px}
.osc-pn-kart h3{margin:0 0 12px;font-size:17px}
.osc-pn-kart.tamam{text-align:center;padding:40px 20px}.osc-pn-kart.tamam .ik{font-size:48px}.osc-pn-kart.tamam p{color:var(--k2);max-width:520px;margin:6px auto 14px}.osc-pn-kart.tamam .osc-pn-btns{justify-content:center}
.osc-pn-tur-sec{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px}
.osc-pn-tur-sec button{display:flex;flex-direction:column;align-items:center;gap:2px;background:#fff;border:2px solid var(--c);border-radius:18px;padding:16px;cursor:pointer;font-family:inherit;color:var(--k)}
.osc-pn-tur-sec button span{font-size:26px}.osc-pn-tur-sec button b{font-size:16px}.osc-pn-tur-sec button small{color:var(--s)}
.osc-pn-tur-sec button.on{border-color:var(--i);background:#eef2ff;box-shadow:0 0 0 4px rgba(79,70,229,.12)}
.osc-pn-ara input,.osc-pn-iz input,.osc-pn-iz select,.osc-pn-iz textarea,.osc-pn-hizli input{width:100%;padding:11px 13px;border:1.5px solid var(--c);border-radius:11px;font-size:15px;font-family:inherit;background:#fff;color:var(--k)}
.osc-pn input:focus,.osc-pn select:focus,.osc-pn textarea:focus{outline:none;border-color:var(--i);box-shadow:0 0 0 4px rgba(79,70,229,.12)}
.osc-pn-testler{display:flex;flex-direction:column;gap:6px;margin-top:10px;max-height:380px;overflow:auto}
.osc-pn-test{text-align:left;background:#fff;border:1px solid var(--c);border-radius:12px;padding:10px 12px;cursor:pointer;font-family:inherit;color:var(--k)}
.osc-pn-test:hover{border-color:var(--i);background:#f8f9ff}
.osc-pn-test b{display:block;font-size:14.5px}.osc-pn-test small{color:var(--s);font-size:12.5px}.osc-pn-test em{color:var(--i);font-style:normal;font-weight:700}
.osc-pn-sec-k{display:flex;align-items:center;gap:12px;background:#eef2ff;border:1.5px solid #c7d2fe;border-radius:14px;padding:12px 14px;margin-top:10px}
.osc-pn-sec-k div{flex:1}.osc-pn-sec-k b{display:block}.osc-pn-sec-k small{color:#4338ca}
.osc-pn-iz{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px}
.osc-pn-iz label{display:flex;flex-direction:column;gap:5px;font-weight:700;font-size:13.5px;color:var(--k2)}
.osc-pn-iz label small{font-weight:500;color:var(--s)}
.osc-pn-iz .genis{grid-column:1/-1}
/* oturum detayı */
.osc-pn-ot-ust{display:grid;grid-template-columns:300px 1fr;gap:16px;margin-bottom:14px}
.osc-pn-kodk{background:var(--k);color:#fff;border-radius:20px;padding:18px;text-align:center}
.osc-pn-kodk small{color:#a5b4fc;font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:11px}
.osc-pn-kodk .kod{font-family:ui-monospace,Menlo,monospace;font-size:42px;font-weight:900;letter-spacing:.12em;margin:2px 0 10px}
.osc-pn-kodk .qr{background:#fff;border-radius:14px;padding:10px;display:inline-block;min-height:152px;min-width:152px}
.osc-pn-kodk .qr img,.osc-pn-kodk .qr canvas{display:block;margin:0 auto}
.osc-pn-kodk .link{display:flex;gap:6px;margin-top:10px}
.osc-pn-kodk .link input{flex:1;min-width:0;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);color:#fff;border-radius:10px;padding:8px;font-size:12px}
.osc-pn-kodk .osc-pn-btns{justify-content:center}
.osc-pn-ot-bilgi{background:#fff;border:1px solid var(--c);border-radius:20px;padding:18px 20px;display:flex;flex-direction:column}
.osc-pn-ot-bilgi .b{display:flex;gap:6px}
.osc-pn-ot-bilgi h2{margin:8px 0 2px;font-size:22px}
.osc-pn-ot-bilgi>small{color:var(--s)}
.osc-pn-say{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:14px 0}
.osc-pn-say div{background:var(--z);border-radius:14px;padding:12px;text-align:center}
.osc-pn-say b{display:block;font-size:26px;font-weight:900}.osc-pn-say small{color:var(--s);font-weight:700;font-size:12px}
.osc-pn-kontrol{margin-top:auto}
.osc-pn-geri-say{font-size:40px;font-weight:900;font-variant-numeric:tabular-nums;color:var(--i)}
.osc-pn-bitti{font-size:18px;font-weight:800;color:var(--k2)}
.osc-pn-son{font-size:14px;color:var(--k2)}.osc-pn-son b{display:block;font-size:20px;color:var(--k)}
.osc-pn-alt-sek{display:flex;gap:4px;flex-wrap:wrap;align-items:center;border-bottom:1px solid var(--c);margin-bottom:14px}
.osc-pn-alt-sek>button{background:none;border:0;border-bottom:3px solid transparent;padding:10px 14px;font-weight:700;font-size:14.5px;color:var(--s);cursor:pointer;font-family:inherit}
.osc-pn-alt-sek>button.on{color:var(--i);border-color:var(--i)}
.osc-pn-alt-sek .sag{margin-left:auto;display:flex;gap:6px;padding-bottom:6px}
.osc-pn-alt-sek .sag .osc-pn-btn{padding:7px 10px;font-size:13px}
.osc-pn-ogrler{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}
.osc-pn-ogr{position:relative;background:#fff;border:1px solid var(--c);border-radius:14px;padding:12px}
.osc-pn-ogr b{display:block;font-size:14.5px;padding-right:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.osc-pn-ogr .e{display:inline-block;font-size:11.5px;font-weight:700;border-radius:999px;padding:2px 8px;margin:4px 0 8px}
.osc-pn-ogr .e.bek{background:#f1f5f9;color:#475569}.osc-pn-ogr .e.coz{background:#e0e7ff;color:#3730a3}.osc-pn-ogr .e.bitti{background:#dcfce7;color:#166534}.osc-pn-ogr .e.cevrimdisi{background:#fef3c7;color:#92400e}
.osc-pn-ogr .bar{height:6px;background:#f1f5f9;border-radius:9px;overflow:hidden}.osc-pn-ogr .bar i{display:block;height:100%;background:var(--i);transition:width .4s}
.osc-pn-ogr.bitti .bar i{background:#10b981}
.osc-pn-ogr small{color:var(--s);font-size:12px}
.osc-pn-ogr .sil{position:absolute;top:6px;right:6px;border:0;background:none;color:#cbd5e1;font-size:18px;cursor:pointer}.osc-pn-ogr .sil:hover{color:#dc2626}
.osc-pn-tablo-kap{overflow-x:auto;background:#fff;border:1px solid var(--c);border-radius:16px}
.osc-pn-tablo{width:100%;border-collapse:collapse;font-size:14px}
.osc-pn-tablo th{background:var(--z);font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--k2);padding:10px 8px}
.osc-pn-tablo th a{color:inherit}
.osc-pn-tablo td{padding:9px 8px;border-top:1px solid #f1f5f9;text-align:center}
.osc-pn-tablo .sol{text-align:left}
.osc-pn-tablo td.d{color:#059669;font-weight:700}.osc-pn-tablo td.y{color:#dc2626;font-weight:700}
.osc-pn-serit{display:flex;gap:2px;flex-wrap:wrap;max-width:420px}
.osc-pn-serit i{width:9px;height:16px;border-radius:2px;background:#e2e8f0}
.osc-pn-serit i.d{background:#10b981}.osc-pn-serit i.y{background:#ef4444}.osc-pn-serit i.n{background:#94a3b8}
.osc-pn-sorular{display:flex;flex-direction:column;gap:8px}
.osc-pn-soru{display:flex;gap:12px;align-items:center;background:#fff;border:1px solid var(--c);border-radius:14px;padding:12px 14px}
.osc-pn-soru .no{width:34px;height:34px;border-radius:10px;background:var(--z);display:flex;align-items:center;justify-content:center;font-weight:800;flex-shrink:0}
.osc-pn-soru .ic{flex:1;min-width:0}
.osc-pn-soru .ust{display:flex;gap:8px;font-size:12px;align-items:center}
.osc-pn-soru .konu{background:#eef2ff;color:#4338ca;border-radius:999px;padding:2px 8px;font-weight:700}
.osc-pn-soru .cevap{color:var(--s)}
.osc-pn-soru p{margin:4px 0 6px;font-size:13.5px;color:var(--k2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.osc-pn-soru .cipler{display:flex;gap:5px;flex-wrap:wrap}
.osc-pn-soru .sc{font-size:12px;border:1px solid var(--c);border-radius:8px;padding:2px 7px;color:var(--k2)}
.osc-pn-soru .sc.dogru{background:#dcfce7;border-color:#86efac;color:#166534}.osc-pn-soru .sc.yanilgi{background:#fee2e2;border-color:#fca5a5;color:#991b1b}.osc-pn-soru .sc.bos{color:var(--s)}
.osc-pn-soru .oran{text-align:right;min-width:78px}.osc-pn-soru .oran b{display:block;font-size:22px;color:var(--r)}.osc-pn-soru .oran small{color:var(--s);font-size:11.5px}
.osc-pn-konular{display:flex;flex-direction:column;gap:8px}
.osc-pn-konu{display:grid;grid-template-columns:minmax(160px,1fr) 2fr 60px;gap:12px;align-items:center;background:#fff;border:1px solid var(--c);border-radius:14px;padding:12px 14px}
.osc-pn-konu b{display:block}.osc-pn-konu small{color:var(--s)}
.osc-pn-konu .bar{height:10px;background:#f1f5f9;border-radius:9px;overflow:hidden}.osc-pn-konu .bar i{display:block;height:100%}
.osc-pn-konu .y{font-size:18px;text-align:right}
.osc-pn-yansit{position:fixed;inset:0;z-index:999999;background:linear-gradient(135deg,#1e1b4b,#0f172a);color:#fff;display:flex;flex-direction:column;justify-content:center;padding:40px;font-family:inherit}
.osc-pn-yansit .kapat{position:absolute;top:18px;right:18px;background:rgba(255,255,255,.12);color:#fff;border:0;border-radius:12px;padding:10px 16px;font-weight:700;cursor:pointer;font-size:15px}
.osc-pn-yansit .ic{display:flex;gap:60px;align-items:center;justify-content:center;flex-wrap:wrap}
.osc-pn-yansit small{display:block;color:#a5b4fc;font-size:22px;font-weight:700;margin-top:18px}
.osc-pn-yansit .adr{display:block;font-size:44px;margin-top:4px}
.osc-pn-yansit .kod{font-family:ui-monospace,Menlo,monospace;font-size:120px;font-weight:900;letter-spacing:.14em;line-height:1.05}
.osc-pn-yansit .say{margin-top:18px;font-size:24px;font-weight:700}
.osc-pn-yansit .sag{text-align:center}.osc-pn-yansit #osc-pn-yqr{background:#fff;padding:16px;border-radius:24px;display:inline-block}
.osc-pn-yansit .isimler{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:30px;max-height:25vh;overflow:hidden}
.osc-pn-yansit .isimler span{background:rgba(255,255,255,.12);border-radius:999px;padding:6px 14px;font-weight:700;font-size:16px;animation:oscPnGel .4s}
@keyframes oscPnGel{from{transform:scale(.6);opacity:0}}
.osc-pn-toast{position:fixed;left:50%;bottom:28px;transform:translateX(-50%);background:#0f172a;color:#fff;padding:12px 20px;border-radius:999px;font-weight:700;z-index:1000000;box-shadow:0 14px 30px -10px rgba(0,0,0,.4);transition:opacity .4s;font-family:inherit;font-size:14.5px;max-width:90vw;text-align:center}
.osc-pn-toast.ok{background:#059669}.osc-pn-toast.hata{background:#dc2626}.osc-pn-toast.git{opacity:0}
/* test editörü */
.osc-pn-bas{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap}
.osc-pn-hizli{display:grid;grid-template-columns:1fr 240px auto;gap:10px;align-items:center;background:var(--z);border-radius:14px;padding:12px 14px}
.osc-pn-hizli b{display:block;font-size:14px}.osc-pn-hizli small{color:var(--s);font-size:12.5px}
.osc-pn-q{background:#fff;border:1px solid var(--c);border-radius:18px;padding:16px 18px;margin-bottom:12px;scroll-margin-top:90px}
.osc-pn-q.vurgu{animation:oscPnVurgu 1.2s}
@keyframes oscPnVurgu{0%{box-shadow:0 0 0 4px rgba(79,70,229,.35)}100%{box-shadow:0 0 0 0 rgba(79,70,229,0)}}
.osc-pn-q.hata{border-color:#ef4444;box-shadow:0 0 0 4px rgba(239,68,68,.12)}
.osc-pn-q-bas{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}
.osc-pn-q-bas .no{width:34px;height:34px;border-radius:10px;background:var(--i);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800}
.osc-pn-q-bas select,.osc-pn-q-bas .konu{padding:8px 10px;border:1.5px solid var(--c);border-radius:10px;font-size:13.5px;font-family:inherit;background:#fff}
.osc-pn-q-bas .konu{width:220px;background:#f8f9ff;border-color:#c7d2fe}
.osc-pn-q-bas .bosluk{flex:1}
.osc-pn-q-bas>button{width:34px;height:34px;border:1px solid var(--c);background:#fff;border-radius:9px;cursor:pointer;font-size:14px;color:var(--k2)}
.osc-pn-q-bas>button:hover{border-color:#94a3b8}.osc-pn-q-bas>button.sil:hover{border-color:#ef4444;background:#fef2f2}
.osc-pn-alan{margin-bottom:10px}.osc-pn-alan.kapali{display:none}
.osc-pn-alan label,.osc-pn-siklar label,.osc-pn-dy label{display:block;font-weight:700;font-size:13px;color:var(--k2);margin-bottom:5px}
.osc-pn-alan label small,.osc-pn-siklar label small{font-weight:500;color:var(--s)}
.osc-pn-arac{display:flex;gap:2px;background:var(--z);border:1.5px solid var(--c);border-bottom:0;border-radius:11px 11px 0 0;padding:4px}
.osc-pn-arac button{border:0;background:transparent;border-radius:7px;padding:5px 9px;cursor:pointer;font-size:13.5px;color:var(--k2);font-family:inherit}
.osc-pn-arac button:hover{background:#fff}
.osc-pn-ce{min-height:46px;border:1.5px solid var(--c);border-radius:0 0 11px 11px;padding:10px 12px;font-size:15px;line-height:1.55;background:#fff;outline:none;overflow-wrap:anywhere}
.osc-pn-ce.kok{min-height:70px;font-weight:600}
.osc-pn-ce.tek{border-radius:11px;min-height:42px;padding:9px 12px}
.osc-pn-ce:focus{border-color:var(--i);box-shadow:0 0 0 4px rgba(79,70,229,.1)}
.osc-pn-ce:empty::before{content:attr(data-ph);color:#94a3b8;font-weight:400}
.osc-pn-ce img{max-width:100%;max-height:260px;border-radius:8px;vertical-align:middle;margin:4px 0}
.osc-pn-link{border:0;background:none;color:var(--i);font-weight:700;cursor:pointer;padding:0 0 10px;font-family:inherit;font-size:13.5px}
.osc-pn-siklar{display:flex;flex-direction:column;gap:6px}
.osc-pn-sik{display:flex;gap:8px;align-items:center}
.osc-pn-sik .harf{width:38px;height:38px;flex-shrink:0;border-radius:50%;border:2px solid #cbd5e1;background:#fff;font-weight:800;color:var(--k2);cursor:pointer;font-family:inherit}
.osc-pn-sik .harf:hover{border-color:#10b981;color:#059669}
.osc-pn-sik .osc-pn-ce{flex:1}
.osc-pn-sik.dogru .harf{background:#10b981;border-color:#10b981;color:#fff}
.osc-pn-sik.dogru .osc-pn-ce{border-color:#86efac;background:#f0fdf4}
.osc-pn-sik .tik{font-size:12px;font-weight:800;color:#059669;white-space:nowrap}
.osc-pn-dy{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.osc-pn-dy label{width:100%}
.osc-pn-dy button{padding:12px 22px;border-radius:12px;border:2px solid var(--c);background:#fff;font-weight:800;cursor:pointer;font-family:inherit;font-size:15px}
.osc-pn-dy button.on{border-color:#10b981;background:#f0fdf4;color:#166534}
.osc-pn-ekle{display:flex;gap:8px;flex-wrap:wrap;align-items:center;background:#fff;border:1.5px dashed #c7d2fe;border-radius:16px;padding:12px 14px;margin-bottom:90px}
.osc-pn-ekle span{font-weight:700;color:var(--k2);font-size:14px}
.osc-pn-ekle button{border:1px solid #c7d2fe;background:#eef2ff;color:#3730a3;border-radius:10px;padding:8px 12px;font-weight:700;cursor:pointer;font-family:inherit}
.osc-pn-alt-bar{position:sticky;bottom:12px;display:flex;gap:8px;align-items:center;background:rgba(15,23,42,.94);color:#fff;border-radius:18px;padding:10px 12px 10px 18px;box-shadow:0 20px 40px -18px rgba(15,23,42,.7);z-index:50;margin-top:-76px}
.osc-pn-alt-bar span{flex:1;font-size:14px}.osc-pn-alt-bar .uyari{color:#fcd34d;font-weight:700}.osc-pn-alt-bar .tamam{color:#86efac;font-weight:700}
.osc-pn-alt-bar .osc-pn-btn:not(.ana){background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.2);color:#fff}
.osc-pn-modal{position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:999999;display:flex;align-items:center;justify-content:center;padding:16px}
.osc-pn-modal-k{background:#fff;border-radius:20px;max-width:760px;width:100%;max-height:90vh;display:flex;flex-direction:column;font-family:inherit}
.osc-pn-modal-k .bas{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid var(--c)}
.osc-pn-modal-k .bas button{border:0;background:var(--z);border-radius:10px;padding:8px 12px;font-weight:700;cursor:pointer}
.osc-pn-modal-k .ic{overflow:auto;padding:16px 20px}
.osc-pn-modal-k .onq{padding:12px 0;border-bottom:1px dashed var(--c)}
.osc-pn-modal-k .onq .n{font-weight:800;color:var(--i)}.osc-pn-modal-k .onq .n span{font-size:12px;background:#eef2ff;border-radius:999px;padding:2px 8px;margin-left:6px}
.osc-pn-modal-k .onq .p{background:var(--z);border-radius:10px;padding:10px;margin:6px 0;font-size:14px}
.osc-pn-modal-k .onq .r{font-weight:700;margin:6px 0}
.osc-pn-modal-k .onq .o{padding:3px 0;font-size:14.5px}.osc-pn-modal-k .onq .o.d{color:#059669;font-weight:700}
.osc-pn-modal-k .onq img{max-width:100%;max-height:240px}
.osc-pn-modal-k .eksik{color:#dc2626;font-weight:700;font-size:13px}
@media (max-width:820px){
 .osc-pn-cta,.osc-pn-tur-sec,.osc-pn-iz,.osc-pn-ot-ust,.osc-pn-hizli{grid-template-columns:1fr}
 .osc-pn-sek{margin-left:0;order:3;width:100%}.osc-pn-sek a{flex:1;text-align:center}
 .osc-pn-say{grid-template-columns:repeat(2,1fr)}
 .osc-pn-q-bas .konu{width:100%;order:5}
 .osc-pn-konu{grid-template-columns:1fr 60px}.osc-pn-konu .bar{grid-column:1/-1;order:3}
 .osc-pn-yansit .kod{font-size:64px}.osc-pn-yansit .adr{font-size:24px}
 .osc-pn-alt-bar{flex-wrap:wrap}.osc-pn-alt-bar span{width:100%;flex:none}
}
/* tema düğme stillerine karşı koruma */
.osc-pn button,.osc-pn-yansit button,.osc-pn-modal button{font-family:inherit!important;text-transform:none!important;letter-spacing:normal!important;text-decoration:none!important;min-height:0;line-height:1.25}
.osc-pn .osc-pn-btn{background:#fff!important;border:1.5px solid var(--c)!important;color:var(--k)!important;padding:9px 14px!important;font-size:14px!important;border-radius:11px!important}
.osc-pn .osc-pn-btn:hover{border-color:#94a3b8!important}
.osc-pn .osc-pn-btn.ana{background:var(--i)!important;border-color:var(--i)!important;color:#fff!important}
.osc-pn .osc-pn-btn.ana:hover{background:var(--id)!important}
.osc-pn .osc-pn-btn.kirmizi{background:#dc2626!important;border-color:#dc2626!important;color:#fff!important}
.osc-pn .osc-pn-btn.kirmizi-y{color:#dc2626!important}
.osc-pn .osc-pn-btn.buyuk{padding:15px 22px!important;font-size:16px!important;border-radius:14px!important}
.osc-pn .osc-pn-kodk .osc-pn-btn:not(.ana){background:rgba(255,255,255,.1)!important;border-color:rgba(255,255,255,.25)!important;color:#fff!important}
.osc-pn .osc-pn-alt-bar .osc-pn-btn:not(.ana){background:rgba(255,255,255,.1)!important;border-color:rgba(255,255,255,.2)!important;color:#fff!important}
.osc-pn .osc-pn-alt-sek .sag .osc-pn-btn,.osc-pn .osc-pn-ok .eylem .osc-pn-btn{padding:7px 10px!important;font-size:13px!important}
.osc-pn .osc-pn-alt-sek>button{background:none!important;border:0!important;border-bottom:3px solid transparent!important;color:var(--s)!important;padding:10px 14px!important;font-size:14.5px!important;border-radius:0!important}
.osc-pn .osc-pn-alt-sek>button.on{color:var(--i)!important;border-bottom-color:var(--i)!important}
.osc-pn .osc-pn-ogr .sil{background:none!important;border:0!important;color:#cbd5e1!important;padding:0 4px!important;font-size:18px!important}
.osc-pn .osc-pn-ogr .sil:hover{color:#dc2626!important}
.osc-pn .osc-pn-tur-sec button{background:#fff!important;border:2px solid var(--c)!important;color:var(--k)!important;padding:16px!important;border-radius:18px!important}
.osc-pn .osc-pn-tur-sec button.on{border-color:var(--i)!important;background:#eef2ff!important}
.osc-pn .osc-pn-test{background:#fff!important;border:1px solid var(--c)!important;color:var(--k)!important;padding:10px 12px!important;border-radius:12px!important;font-size:inherit!important}
.osc-pn .osc-pn-test:hover{border-color:var(--i)!important;background:#f8f9ff!important}
.osc-pn .osc-pn-q-bas>button{background:#fff!important;border:1px solid var(--c)!important;color:var(--k2)!important;padding:0!important;font-size:14px!important;border-radius:9px!important}
.osc-pn .osc-pn-arac button{background:transparent!important;border:0!important;color:var(--k2)!important;padding:5px 9px!important;font-size:13.5px!important;border-radius:7px!important}
.osc-pn .osc-pn-arac button:hover{background:#fff!important}
.osc-pn .osc-pn-sik .harf{background:#fff!important;border:2px solid #cbd5e1!important;color:var(--k2)!important;padding:0!important;font-size:15px!important;border-radius:50%!important}
.osc-pn .osc-pn-sik.dogru .harf{background:#10b981!important;border-color:#10b981!important;color:#fff!important}
.osc-pn .osc-pn-dy button{background:#fff!important;border:2px solid var(--c)!important;color:var(--k)!important;padding:12px 22px!important;font-size:15px!important;border-radius:12px!important}
.osc-pn .osc-pn-dy button.on{border-color:#10b981!important;background:#f0fdf4!important;color:#166534!important}
.osc-pn .osc-pn-ekle button{background:#eef2ff!important;border:1px solid #c7d2fe!important;color:#3730a3!important;padding:8px 12px!important;font-size:14px!important;border-radius:10px!important}
.osc-pn .osc-pn-link{background:none!important;border:0!important;color:var(--i)!important;padding:0 0 10px!important;font-size:13.5px!important}
.osc-pn-yansit .kapat{background:rgba(255,255,255,.12)!important;color:#fff!important;border:0!important;padding:10px 16px!important}
.osc-pn-modal .bas button{background:#f6f7fb!important;color:#0f172a!important;border:0!important;padding:8px 12px!important}
.osc-pn-kodk .qr:empty{display:none}
.osc-pn .osc-pn-tablo th,.osc-pn .osc-pn-tablo td{border:0!important;border-top:1px solid #f1f5f9!important}.osc-wrapper .osc-sk-tablo th,.osc-wrapper .osc-sk-tablo td{border:0;border-top:1px solid #f1f5f9}

.osc-pn .osc-pn-test{display:block!important;width:100%!important;height:auto!important;white-space:normal!important;float:none!important;position:static!important;text-align:left!important;line-height:1.4!important;min-height:0!important;outline:0}
.osc-pn .osc-pn-test b{display:block;font-size:14.5px;white-space:normal}.osc-pn .osc-pn-test small{display:block;margin-top:2px}
.osc-pn .osc-pn-test:focus{border-color:var(--i)!important}
.osc-pn-selam{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;flex-wrap:wrap;margin:2px 0 14px}
.osc-pn-selam small{color:var(--s);font-weight:700}.osc-pn-selam h2{margin:2px 0 0;font-size:26px}
.osc-pn-mini{display:flex;gap:8px;flex-wrap:wrap}
.osc-pn-mini div{background:#fff;border:1px solid var(--c);border-radius:14px;padding:8px 14px;text-align:center;min-width:86px}
.osc-pn-mini b{display:block;font-size:20px}.osc-pn-mini small{color:var(--s);font-size:11.5px;font-weight:700}
.osc-pn-dosya-k{display:flex;gap:14px;align-items:center;background:linear-gradient(135deg,#eef2ff,#faf5ff);border:1.5px dashed #a5b4fc;border-radius:16px;padding:14px 16px;margin-bottom:12px}
.osc-pn-dosya-k .ik{font-size:30px}.osc-pn-dosya-k .ac{flex:1}.osc-pn-dosya-k b{display:block}.osc-pn-dosya-k small{color:var(--k2);font-size:13px}
#osc-pn-dosya-durum{display:block;margin-top:4px;font-size:13px;font-weight:700;color:var(--i)}#osc-pn-dosya-durum.ok{color:#059669}#osc-pn-dosya-durum.hata{color:#dc2626}
@media (max-width:820px){
 .osc-pn{padding:0 12px}
 .osc-pn-ust{border-radius:16px;padding:12px}
 .osc-pn-tur-sec{grid-template-columns:1fr 1fr;gap:8px}
 .osc-pn .osc-pn-tur-sec button{padding:12px 6px!important}.osc-pn-tur-sec button small{font-size:11.5px}
 .osc-pn-kart{padding:14px;border-radius:16px}
 .osc-pn-dosya-k{flex-wrap:wrap}.osc-pn-dosya-k .osc-pn-btn{width:100%}
 .osc-pn-mini{width:100%}.osc-pn-mini div{flex:1;min-width:0;padding:8px 4px}
 .osc-pn-kodk .kod{font-size:34px}
 .osc-pn-alt-sek{overflow-x:auto;flex-wrap:nowrap}.osc-pn-alt-sek>button{white-space:nowrap}.osc-pn-alt-sek .sag{margin-left:0}
}

.osc-pn-marka .lg{background:#fff;border-radius:12px;padding:6px 10px;display:flex;align-items:center}.osc-pn-marka .lg img{height:28px;width:auto;display:block}
</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script>
<script>window.OSC_PN = <?php echo wp_json_encode($cfg); ?>;</script>
<script>(function () {
  'use strict';
  var C = window.OSC_PN, kok = document.getElementById('osc-pn');
  if (!C || !kok) return;
  var zam = null, sayac = null;
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
  function api(action, data) {
    var fd = new URLSearchParams(); fd.append('action', 'osc_sp_' + action); fd.append('nonce', C.nonce);
    Object.keys(data || {}).forEach(function (k) { if (data[k] !== undefined && data[k] !== null) fd.append(k, data[k]); });
    return fetch(C.ajax, { method: 'POST', body: fd, credentials: 'same-origin' }).then(function (r) { return r.json(); }).then(function (j) {
      if (!j || !j.success) throw new Error(j && typeof j.data === 'string' ? j.data : 'İşlem yapılamadı.');
      return j.data;
    });
  }
  function bildir(m, tur) {
    var t = document.createElement('div'); t.className = 'osc-pn-toast ' + (tur || ''); t.textContent = m; document.body.appendChild(t);
    setTimeout(function () { t.classList.add('git'); }, 2800); setTimeout(function () { t.remove(); }, 3300);
  }
  function durdur() { clearInterval(zam); clearInterval(sayac); zam = sayac = null; }
  function sure(sn) { sn = Math.max(0, sn | 0); var h = Math.floor(sn / 3600), m = Math.floor(sn % 3600 / 60), s = sn % 60, p = function (x) { return x < 10 ? '0' + x : x; }; return (h ? h + ':' + p(m) : m) + ':' + p(s); }
  function n2(x) { return Math.round(x * 100) / 100; }
  var DURUM = { bekliyor: ['Başlamadı', 'gri'], basladi: ['Devam ediyor', 'yesil'], bitti: ['Bitti', 'koyu'] };

  function cerceve(aktif, ic) {
    kok.innerHTML = '<div class="osc-pn-ust"><div class="osc-pn-marka"><a class="lg" href="' + esc(C.home) + '"><img src="' + C.logo + '" alt="soruindir.net"></a><div><b>Öğretmen Paneli</b><small>' + esc(C.site) + '</small></div></div>' +
      '<nav class="osc-pn-sek"><a href="#" class="' + (aktif === 'ot' ? 'on' : '') + '">Sınıf oturumlarım</a><a href="#testler" class="' + (aktif === 'test' ? 'on' : '') + '">Testlerim</a>' + (C.yz ? '<a href="#yazili" class="' + (aktif === 'yz' ? 'on' : '') + '">📄 Yazılı hazırla</a>' : (C.yazili ? '<a href="' + esc(C.yazili) + '">Yazılı hazırla</a>' : '')) + '</nav>' +
      '<div class="osc-pn-kim">' + esc(C.ad) + ' · <a href="' + esc(C.cikis) + '">Çıkış</a></div></div><div class="osc-pn-ic">' + ic + '</div>';
  }
  function yonlendir() {
    durdur();
    var h = (location.hash || '').replace(/^#/, '').split('/');
    if (h[0] === 'yeni') return vYeni(h[1] === 'odev' ? 'odev' : 'canli', +h[2] || 0);
    if (h[0] === 'oturum') return vOturum(+h[1]);
    if (h[0] === 'testler') return vTestler();
    if (h[0] === 'yazili' && C.yz) return vYazili();
    if (h[0] === 'test') return vEditor(h[1] === 'kopya' ? +h[2] : +h[1] || 0, h[1] === 'kopya');
    if (C.yeni) { var y = C.yeni; C.yeni = 0; location.hash = 'yeni/canli/' + y; return; }
    vOturumlar();
  }
  function vYazili() {
    cerceve('yz', '<div id="osc-yz" class="osc-yz gomulu"><div class="yz-yuk">Yükleniyor…</div></div>');
    window.OSC_YZ = C.yz;
    if (!document.getElementById('osc-yz-css')) { var l = document.createElement('link'); l.id = 'osc-yz-css'; l.rel = 'stylesheet'; l.href = C.yz_css; document.head.appendChild(l); var f = document.createElement('link'); f.rel = 'stylesheet'; f.href = 'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap'; document.head.appendChild(f); }
    if (window.OSC_YZ_BASLAT) return window.OSC_YZ_BASLAT();
    if (document.getElementById('osc-yz-js')) return;
    var sc = document.createElement('script'); sc.id = 'osc-yz-js'; sc.src = C.yz_js; sc.onerror = function () { var e = document.getElementById('osc-yz'); if (e) e.innerHTML = '<div class="yz-yuk">Yazılı aracı yüklenemedi. Sayfayı yenileyin.</div>'; }; document.head.appendChild(sc);
  }
  window.addEventListener('hashchange', yonlendir);

  /* ======================= oturum listesi ======================= */
  function vOturumlar() {
    cerceve('ot', '<div class="osc-pn-selam"><div><small>Hoş geldiniz 👋</small><h2>' + esc(C.ad) + '</h2></div><div class="osc-pn-mini" id="osc-pn-mini"></div></div><div class="osc-pn-cta"><a href="#yeni/canli" class="osc-pn-cta-k canli"><span>🔴</span><div><b>Canlı sınıf sınavı başlat</b><small>Öğrenciler kodla katılır, hepsi aynı anda başlar, siz canlı izlersiniz.</small></div></a><a href="#yeni/odev" class="osc-pn-cta-k odev"><span>📚</span><div><b>Ödev linki oluştur</b><small>Son teslim tarihli link gönderin; sonuçlar burada toplanır.</small></div></a></div>' +
      '<h2 class="osc-pn-h2">Oturumlarım</h2><div id="osc-pn-liste" class="osc-pn-liste"><div class="osc-pn-bos">Yükleniyor…</div></div>');
    api('oturumlar').then(function (l) {
      var el = document.getElementById('osc-pn-liste'); if (!el) return;
      var mini = document.getElementById('osc-pn-mini'), kat = 0, bit = 0, aktif = 0; l.forEach(function (o) { kat += o.katilan; bit += o.biten; if (o.durum !== 'bitti') aktif++; });
      if (mini) mini.innerHTML = '<div><b>' + l.length + '</b><small>Oturum</small></div><div><b>' + aktif + '</b><small>Aktif</small></div><div><b>' + kat + '</b><small>Öğrenci katılımı</small></div><div><b>' + bit + '</b><small>Teslim</small></div>';
      if (!l.length) { el.innerHTML = '<div class="osc-pn-bos"><b>Henüz oturum yok.</b><br>Yukarıdan ilk canlı sınavınızı başlatın ya da bir ödev linki oluşturun.</div>'; return; }
      el.innerHTML = l.map(function (o) {
        var d = DURUM[o.durum] || ['', ''];
        return '<a class="osc-pn-ok" href="#oturum/' + o.id + '"><div class="ust"><span class="tur ' + o.tur + '">' + (o.tur === 'odev' ? 'Ödev' : 'Canlı') + '</span><span class="cip ' + d[1] + '">' + d[0] + '</span><span class="kod">' + esc(o.kod) + '</span></div><b>' + esc(o.baslik) + '</b><small>' + esc(o.test) + '</small>' +
          '<div class="alt"><span>👥 ' + o.katilan + ' katılım</span><span>✅ ' + o.biten + ' teslim</span>' + (o.ort !== null ? '<span>Ort. net ' + o.ort + '</span>' : '') + '</div><small class="tarih">' + esc(o.tarih) + (o.son_tarih ? ' · son teslim ' + esc(o.son_tarih) : '') + '</small></a>';
      }).join('');
    }).catch(function (e) { bildir(e.message, 'hata'); });
  }

  /* ======================= yeni oturum ======================= */
  function vYeni(tur, qid) {
    var secili = null;
    var yarin = new Date(Date.now() + 7 * 864e5); yarin.setHours(23, 59, 0, 0);
    var yerel = function (d) { var p = function (x) { return x < 10 ? '0' + x : x; }; return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + 'T' + p(d.getHours()) + ':' + p(d.getMinutes()); };
    cerceve('ot', '<a href="#" class="osc-pn-geri">‹ Oturumlarım</a><h2 class="osc-pn-h2">Yeni oturum</h2>' +
      '<div class="osc-pn-tur-sec"><button type="button" data-tur="canli" class="' + (tur === 'canli' ? 'on' : '') + '"><span>🔴</span><b>Canlı sınıf</b><small>Herkes aynı anda başlar</small></button><button type="button" data-tur="odev" class="' + (tur === 'odev' ? 'on' : '') + '"><span>📚</span><b>Ödev linki</b><small>Son teslim tarihine kadar</small></button></div>' +
      '<div class="osc-pn-kart"><h3>1. Test seçin</h3><div class="osc-pn-ara"><input id="osc-pn-q" placeholder="Test ara (ör. LGS Matematik, Üslü sayılar)…" autocomplete="off"></div><div id="osc-pn-sonuc" class="osc-pn-testler"></div><div id="osc-pn-secili"></div></div>' +
      '<div class="osc-pn-kart" id="osc-pn-ayar" style="display:none"><h3>2. Ayarlar</h3><div class="osc-pn-iz">' +
      '<label>Oturum adı<input id="osc-pn-baslik" placeholder="Örn: 8-A Matematik"></label>' +
      '<label>Süre (dakika)<input id="osc-pn-sure" type="number" min="0" max="600"><small>0 yazarsanız süre sınırı olmaz.</small></label>' +
      '<label class="odev-al">Son teslim<input id="osc-pn-son" type="datetime-local" value="' + yerel(yarin) + '"></label>' +
      '<label>Doğru cevaplar<select id="osc-pn-goster"><option value="bitince">Oturum bitince öğrenciye gösterilsin</option><option value="hemen">Öğrenci bitirir bitirmez gösterilsin</option></select><small>Kopya riskine karşı “oturum bitince” önerilir.</small></label>' +
      '</div><button type="button" class="osc-pn-btn ana buyuk" id="osc-pn-olustur">Oturumu oluştur →</button></div>');
    var ayarEl = document.getElementById('osc-pn-ayar');
    function turYaz() { kok.querySelectorAll('.osc-pn-tur-sec button').forEach(function (b) { b.classList.toggle('on', b.dataset.tur === tur); }); kok.querySelectorAll('.odev-al').forEach(function (e) { e.style.display = tur === 'odev' ? '' : 'none'; }); }
    kok.querySelectorAll('.osc-pn-tur-sec button').forEach(function (b) { b.onclick = function () { tur = b.dataset.tur; turYaz(); }; });
    turYaz();
    function sec(t) {
      secili = t;
      document.getElementById('osc-pn-sonuc').innerHTML = '';
      document.getElementById('osc-pn-secili').innerHTML = '<div class="osc-pn-sec-k"><div><b>' + esc(t.baslik) + '</b><small>' + t.soru + ' soru · ' + esc(t.tur) + ' (' + (t.kural ? t.kural + ' yanlış 1 doğru' : 'yanlış götürmez') + ')' + (t.kategori ? ' · ' + esc(t.kategori) : '') + '</small></div><button type="button" class="osc-pn-btn" id="osc-pn-degis">Değiştir</button></div>';
      document.getElementById('osc-pn-degis').onclick = function () { secili = null; document.getElementById('osc-pn-secili').innerHTML = ''; ayarEl.style.display = 'none'; document.getElementById('osc-pn-q').focus(); ara(''); };
      document.getElementById('osc-pn-sure').value = t.sure || 0;
      if (!document.getElementById('osc-pn-baslik').value) document.getElementById('osc-pn-baslik').value = t.baslik;
      ayarEl.style.display = '';
    }
    var araT = null, son = [];
    function ara(q) {
      api('ara', { q: q }).then(function (l) {
        son = l; var el = document.getElementById('osc-pn-sonuc'); if (!el || secili) return;
        el.innerHTML = l.length ? l.map(function (t, i) { return '<div role="button" tabindex="0" class="osc-pn-test" data-i="' + i + '"><b>' + esc(t.baslik) + '</b><small>' + t.soru + ' soru · ' + esc(t.tur) + (t.sure ? ' · ' + t.sure + ' dk' : '') + (t.benim ? ' · <em>' + (t.durum === 'publish' ? 'testim' : 'testim (onay bekliyor/taslak)') + '</em>' : '') + '</small></div>'; }).join('') : '<div class="osc-pn-bos">Sonuç yok.</div>';
        el.querySelectorAll('.osc-pn-test').forEach(function (b) { b.onclick = function () { sec(son[+b.dataset.i]); }; });
      }).catch(function (e) { bildir(e.message, 'hata'); });
    }
    document.getElementById('osc-pn-q').oninput = function (e) { clearTimeout(araT); var v = e.target.value; araT = setTimeout(function () { ara(v); }, 300); };
    if (qid) api('ara', { id: qid }).then(function (l) { if (l[0]) sec(l[0]); else ara(''); }).catch(function () { ara(''); }); else ara('');
    document.getElementById('osc-pn-olustur').onclick = function (e) {
      if (!secili) return bildir('Önce bir test seçin.', 'hata');
      e.target.disabled = true;
      api('olustur', { quiz_id: secili.id, tur: tur, baslik: document.getElementById('osc-pn-baslik').value, sure: document.getElementById('osc-pn-sure').value, son_tarih: tur === 'odev' ? document.getElementById('osc-pn-son').value : '', sonuc_goster: document.getElementById('osc-pn-goster').value })
        .then(function (r) { location.hash = 'oturum/' + r.id; })
        .catch(function (er) { e.target.disabled = false; bildir(er.message, 'hata'); });
    };
  }

  /* ======================= oturum detay (canlı izleme + rapor) ======================= */
  function vOturum(id) {
    var V = null, sekme = 'canli', siralama = 'net', qrCizildi = false, yansit = false;
    cerceve('ot', '<a href="#" class="osc-pn-geri">‹ Oturumlarım</a><div id="osc-pn-ot"><div class="osc-pn-bos">Yükleniyor…</div></div>');
    function yukle() {
      return api('izle', { id: id, rapor: 1 }).then(function (v) { V = v; ciz(); }).catch(function (e) { bildir(e.message, 'hata'); durdur(); });
    }
    function sayilar() {
      var k = V.katilimcilar, s = { top: k.length, bek: 0, coz: 0, bit: 0, net: 0 };
      k.forEach(function (x) { if (x.durum === 'bitti') { s.bit++; s.net += x.net; } else if (x.durum === 'cozuyor') s.coz++; else s.bek++; });
      s.ort = s.bit ? n2(s.net / s.bit) : '–'; return s;
    }
    function ciz() {
      var el = document.getElementById('osc-pn-ot'); if (!el) return;
      var s = sayilar(), d = DURUM[V.durum] || ['', ''];
      var kontrol = '';
      if (V.tur === 'canli') {
        if (V.durum === 'bekliyor') kontrol = '<button class="osc-pn-btn ana buyuk" data-k="baslat">▶ Sınavı başlat</button><small class="osc-pn-not">Öğrenciler katıldıkça aşağıda görünür. Hazır olunca başlatın; herkesin süresi aynı anda başlar.</small>';
        else if (V.durum === 'basladi') kontrol = '<div class="osc-pn-geri-say" id="osc-pn-gs">' + (V.sure ? sure(V.kalan) : 'Süresiz') + '</div><div class="osc-pn-btns">' + (V.sure ? '<button class="osc-pn-btn" data-k="sure_ekle" data-dk="5">+5 dk</button>' : '') + '<button class="osc-pn-btn kirmizi" data-k="bitir">■ Sınavı bitir</button></div>';
        else kontrol = '<div class="osc-pn-bitti">Oturum bitti</div><div class="osc-pn-btns"><button class="osc-pn-btn" data-k="sil">Oturumu sil</button></div>';
      } else {
        kontrol = (V.durum === 'bitti' ? '<div class="osc-pn-bitti">Ödev kapandı</div>' : '<div class="osc-pn-son">Son teslim<b>' + esc(V.son_tarih || 'yok') + '</b></div>') + '<div class="osc-pn-btns">' + (V.son_tarih ? '<button class="osc-pn-btn" data-k="sure_ekle" data-dk="1440">+1 gün</button>' : '') + (V.durum !== 'bitti' ? '<button class="osc-pn-btn kirmizi" data-k="bitir">Ödevi kapat</button>' : '<button class="osc-pn-btn" data-k="sil">Sil</button>') + '</div>';
      }
      if (!el.querySelector('.osc-pn-ot-ust')) {
        el.innerHTML = '<div class="osc-pn-ot-ust"><div class="osc-pn-kodk"><small>Katılım kodu</small><div class="kod">' + esc(V.kod) + '</div><div id="osc-pn-qr" class="qr"></div><div class="link"><input readonly value="' + esc(V.link) + '"><button class="osc-pn-btn" data-k="kopyala">Kopyala</button></div><div class="osc-pn-btns"><button class="osc-pn-btn" data-k="yansit">📺 Tahtaya yansıt</button><a class="osc-pn-btn" target="_blank" rel="noopener" href="https://api.whatsapp.com/send?text=' + encodeURIComponent(V.baslik + ' sınavına katılmak için: ' + V.link) + '">WhatsApp</a></div></div>' +
          '<div class="osc-pn-ot-bilgi"><div class="b"><span class="tur ' + V.tur + '">' + (V.tur === 'odev' ? 'Ödev' : 'Canlı sınıf') + '</span><span class="cip" id="osc-pn-dur"></span></div><h2>' + esc(V.baslik) + '</h2><small>' + esc(V.test) + ' · ' + V.soru + ' soru · ' + (V.kural ? V.kural + ' yanlış 1 doğruyu götürür' : 'yanlış götürmez') + '</small><div class="osc-pn-say" id="osc-pn-say"></div><div id="osc-pn-kontrol" class="osc-pn-kontrol"></div></div></div>' +
          '<nav class="osc-pn-alt-sek"><button data-s="canli">Canlı izleme</button><button data-s="ogr">Öğrenci sonuçları</button><button data-s="soru">Soru analizi</button><button data-s="konu">Konu analizi</button><span class="sag"><button class="osc-pn-btn" data-k="csv">⬇ Excel (CSV)</button><button class="osc-pn-btn" data-k="yazdir">🖨 Yazdır</button></span></nav><div id="osc-pn-govde"></div>';
        el.onclick = tikla;
      }
      document.getElementById('osc-pn-dur').className = 'cip ' + d[1]; document.getElementById('osc-pn-dur').textContent = d[0];
      document.getElementById('osc-pn-say').innerHTML = '<div><b>' + s.top + '</b><small>Katılan</small></div><div><b>' + s.coz + '</b><small>Çözüyor</small></div><div><b>' + s.bit + '</b><small>Teslim etti</small></div><div><b>' + s.ort + '</b><small>Ort. net</small></div>';
      var kk = document.getElementById('osc-pn-kontrol'); if (kk.dataset.h !== kontrol) { kk.innerHTML = kontrol; kk.dataset.h = kontrol; }
      if (!window.QRCode) { var qe = document.getElementById('osc-pn-qr'); if (qe) qe.style.display = 'none'; }
      if (!qrCizildi && window.QRCode) { try { new QRCode(document.getElementById('osc-pn-qr'), { text: V.link, width: 132, height: 132, correctLevel: QRCode.CorrectLevel.M }); qrCizildi = true; } catch (e) {} }
      kok.querySelectorAll('.osc-pn-alt-sek [data-s]').forEach(function (b) { b.classList.toggle('on', b.dataset.s === sekme); });
      var g = document.getElementById('osc-pn-govde');
      g.innerHTML = sekme === 'canli' ? canliHtml() : sekme === 'ogr' ? ogrHtml() : sekme === 'soru' ? soruHtml() : konuHtml();
      if (yansit) yansitCiz();
      clearInterval(sayac);
      if (V.durum === 'basladi' && V.tur === 'canli' && V.sure) { var bit = Date.now() + V.kalan * 1000; sayac = setInterval(function () { var e = document.getElementById('osc-pn-gs'); if (e) e.textContent = sure((bit - Date.now()) / 1000); }, 500); }
    }
    function canliHtml() {
      var k = V.katilimcilar;
      if (!k.length) return '<div class="osc-pn-bos big"><b>Henüz katılan yok.</b><br>Öğrenciler <b>' + esc(V.katil_link) + '</b> adresine girip <b>' + esc(V.kod) + '</b> kodunu yazarak ya da karekodu okutarak katılabilir.</div>';
      return '<div class="osc-pn-ogrler">' + k.map(function (x) {
        var yuzde = V.soru ? Math.round(x.ilerleme / V.soru * 100) : 0;
        var etiket = x.durum === 'bitti' ? '<span class="e bitti">%' + x.puan + ' · ' + n2(x.net) + ' net</span>' : x.durum === 'cozuyor' ? (x.cevrimici ? '<span class="e coz">Çözüyor</span>' : '<span class="e cevrimdisi">Bağlantı yok</span>') : '<span class="e bek">Bekliyor</span>';
        return '<div class="osc-pn-ogr ' + x.durum + '"><button class="sil" title="Çıkar" data-k="katilimci_sil" data-id="' + x.id + '">×</button><b>' + esc(x.ad) + '</b>' + etiket + '<div class="bar"><i style="width:' + (x.durum === 'bitti' ? 100 : yuzde) + '%"></i></div><small>' + x.ilerleme + ' / ' + V.soru + ' cevap</small></div>';
      }).join('') + '</div>';
    }
    function bitenler() { return V.katilimcilar.filter(function (x) { return x.durum === 'bitti' && x.durumlar; }); }
    function ogrHtml() {
      var l = bitenler().slice();
      if (!l.length) return '<div class="osc-pn-bos big">Teslim eden öğrenci olunca sonuçlar burada listelenir.</div>';
      l.sort(function (a, b) { return siralama === 'ad' ? a.ad.localeCompare(b.ad, 'tr') : (b.net - a.net) || (a.sure - b.sure); });
      return '<div class="osc-pn-tablo-kap"><table class="osc-pn-tablo"><thead><tr><th>#</th><th class="sol"><a href="#" data-k="sirala" data-v="ad">Öğrenci</a></th><th>D</th><th>Y</th><th>B</th><th><a href="#" data-k="sirala" data-v="net">Net ▾</a></th><th>Puan</th><th>Süre</th><th class="sol">Sorular</th></tr></thead><tbody>' + l.map(function (x, i) {
        return '<tr><td>' + (i + 1) + '</td><td class="sol"><b>' + esc(x.ad) + '</b></td><td class="d">' + n2(x.d) + '</td><td class="y">' + n2(x.y) + '</td><td>' + x.b + '</td><td><b>' + n2(x.net) + '</b></td><td>%' + x.puan + '</td><td>' + (x.sure ? sure(x.sure) : '–') + '</td><td class="sol"><div class="osc-pn-serit">' + x.durumlar.map(function (s, j) { return '<i class="' + s + '" title="' + (j + 1) + '. soru"></i>'; }).join('') + '</div></td></tr>';
      }).join('') + '</tbody></table></div>';
    }
    function soruIstat() {
      var l = bitenler();
      return (V.sorular || []).map(function (q, i) {
        var dag = {}, d = 0, b = 0;
        l.forEach(function (x) { var s = x.durumlar[i], c = x.cevaplar ? x.cevaplar[i] : null; if (s === 'd') d++; if (s === 'b') b++; else if (c && (q.tur === 'multiple' || q.tur === 'truefalse')) dag[c] = (dag[c] || 0) + 1; });
        return { i: i, q: q, d: d, b: b, n: l.length, oran: l.length ? d / l.length : 0, dag: dag };
      });
    }
    function soruHtml() {
      var st = soruIstat();
      if (!bitenler().length) return '<div class="osc-pn-bos big">Teslim eden öğrenci olunca her sorunun başarı oranı burada görünür.</div>';
      var sirali = st.slice().sort(function (a, b) { return a.oran - b.oran; });
      return '<p class="osc-pn-not">En zor sorular üstte. Kırmızı şık, yanlış cevaplarda en çok seçilen şıktır (yaygın yanılgı).</p><div class="osc-pn-sorular">' + sirali.map(function (x) {
        var y = Math.round(x.oran * 100), harf = function (k) { return x.q.tur === 'truefalse' ? (k === 'A' ? 'D' : 'Y') : k; };
        var enCok = null; Object.keys(x.dag).forEach(function (k) { if (k !== x.q.dogru && (!enCok || x.dag[k] > x.dag[enCok])) enCok = k; });
        var cipler = (x.q.secenekler || []).map(function (k) { return '<span class="sc ' + (k === x.q.dogru ? 'dogru' : (k === enCok ? 'yanilgi' : '')) + '">' + harf(k) + ' <b>' + (x.dag[k] || 0) + '</b></span>'; }).join('') + '<span class="sc bos">Boş <b>' + x.b + '</b></span>';
        return '<div class="osc-pn-soru"><div class="no">' + (x.i + 1) + '</div><div class="ic"><div class="ust">' + (x.q.konu ? '<span class="konu">' + esc(x.q.konu) + '</span>' : '') + '<span class="cevap">Doğru: <b>' + esc(x.q.tur === 'truefalse' ? (x.q.dogru === 'A' ? 'Doğru' : 'Yanlış') : x.q.dogru) + '</b></span></div><p>' + esc(x.q.kok || '(görsel soru)') + '</p><div class="cipler">' + cipler + '</div></div><div class="oran" style="--r:' + (y >= 70 ? '#10b981' : y >= 40 ? '#f59e0b' : '#ef4444') + '"><b>%' + y + '</b><small>' + x.d + '/' + x.n + ' doğru</small></div></div>';
      }).join('') + '</div>';
    }
    function konuHtml() {
      var st = soruIstat(), k = {};
      if (!bitenler().length) return '<div class="osc-pn-bos big">Teslim eden öğrenci olunca sınıfın konu bazında başarısı burada görünür.</div>';
      st.forEach(function (x) { var ad = x.q.konu || 'Konusu belirtilmemiş'; var o = k[ad] || (k[ad] = { soru: 0, d: 0, n: 0 }); o.soru++; o.d += x.d; o.n += x.n; });
      var l = Object.keys(k).map(function (ad) { return { ad: ad, o: k[ad], oran: k[ad].n ? k[ad].d / k[ad].n : 0 }; }).sort(function (a, b) { return a.oran - b.oran; });
      return '<p class="osc-pn-not">Sınıfın en zorlandığı konular üstte.</p><div class="osc-pn-konular">' + l.map(function (x) { var y = Math.round(x.oran * 100); return '<div class="osc-pn-konu"><div><b>' + esc(x.ad) + '</b><small>' + x.o.soru + ' soru</small></div><div class="bar"><i style="width:' + y + '%;background:' + (y >= 70 ? '#10b981' : y >= 40 ? '#f59e0b' : '#ef4444') + '"></i></div><b class="y">%' + y + '</b></div>'; }).join('') + '</div>';
    }
    function csv() {
      var l = bitenler(), sat = [['Sıra', 'Öğrenci', 'Doğru', 'Yanlış', 'Boş', 'Net', 'Puan', 'Süre'].concat((V.sorular || []).map(function (q, i) { return 'S' + (i + 1); }))];
      l.slice().sort(function (a, b) { return b.net - a.net; }).forEach(function (x, i) { sat.push([i + 1, x.ad, n2(x.d), n2(x.y), x.b, String(n2(x.net)).replace('.', ','), x.puan, x.sure ? sure(x.sure) : ''].concat(x.durumlar.map(function (s, j) { return (x.cevaplar && x.cevaplar[j]) ? x.cevaplar[j] + (s === 'd' ? ' ✓' : s === 'y' ? ' ✗' : '') : (s === 'b' ? '' : s); }))); });
      sat.push([]); sat.push(['Doğru cevap', '', '', '', '', '', '', ''].concat((V.sorular || []).map(function (q) { return q.dogru; })));
      var txt = '﻿' + sat.map(function (r) { return r.map(function (c) { c = String(c == null ? '' : c); return /[;"\n]/.test(c) ? '"' + c.replace(/"/g, '""') + '"' : c; }).join(';'); }).join('\r\n');
      var a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([txt], { type: 'text/csv;charset=utf-8' })); a.download = (V.baslik || 'sonuclar').replace(/[^\wçğıöşüÇĞİÖŞÜ\- ]+/g, '') + '-sonuclar.csv'; document.body.appendChild(a); a.click(); setTimeout(function () { a.remove(); }, 500);
    }
    function yazdir() {
      var w = window.open('', '_blank'); if (!w) return bildir('Açılır pencere engellendi.', 'hata');
      var s = sayilar();
      w.document.write('<!doctype html><html lang="tr"><head><meta charset="utf-8"><title>' + esc(V.baslik) + ' — Sonuç raporu</title><style>body{font-family:Arial,sans-serif;color:#111;margin:24px}h1{font-size:20px;margin:0}small{color:#555}table{border-collapse:collapse;width:100%;margin-top:12px;font-size:12px}th,td{border:1px solid #bbb;padding:4px 6px;text-align:center}th{background:#eef}td.sol,th.sol{text-align:left}.oz{display:flex;gap:20px;margin:10px 0;font-size:13px}.osc-pn-serit{display:flex;gap:1px}.osc-pn-serit i{width:8px;height:12px;display:inline-block}.d{background:#10b981}.y{background:#ef4444}.b{background:#ddd}.n{background:#999}h2{font-size:15px;margin:22px 0 4px}@media print{body{margin:10mm}}</style></head><body>' +
        '<h1>' + esc(V.baslik) + '</h1><small>' + esc(V.test) + ' · ' + V.soru + ' soru · ' + esc(new Date().toLocaleString('tr-TR')) + '</small><div class="oz"><span>Katılan: <b>' + s.top + '</b></span><span>Teslim: <b>' + s.bit + '</b></span><span>Ortalama net: <b>' + s.ort + '</b></span></div>' +
        '<h2>Öğrenci sonuçları</h2>' + ogrHtml().replace(/<a [^>]*>([^<]*)<\/a>/g, '$1').replace(/class="d"/g, '').replace(/class="y"/g, '') +
        '<h2>Konu analizi</h2>' + konuHtml().replace(/<div class="bar">.*?<\/div>/g, '') + '<p style="margin-top:30px;font-size:11px;color:#777">soruindir.net Öğretmen Paneli</p><script>window.onload=function(){window.print()}<\/script></body></html>');
      w.document.close();
    }
    function yansitCiz() {
      var z = document.getElementById('osc-pn-yansit');
      if (!z) { z = document.createElement('div'); z.id = 'osc-pn-yansit'; z.className = 'osc-pn-yansit'; document.body.appendChild(z); z.onclick = function (e) { if (e.target.dataset.k === 'kapat') { yansit = false; z.remove(); if (document.fullscreenElement) document.exitFullscreen().catch(function () {}); } }; }
      var s = sayilar();
      z.innerHTML = '<button class="kapat" data-k="kapat">× Kapat</button><div class="ic"><div class="sol"><small>1. Telefonundan şu adrese gir</small><b class="adr">' + esc(V.katil_link.replace(/^https?:\/\//, '')) + '</b><small>2. Kodu yaz</small><div class="kod">' + esc(V.kod) + '</div><div class="say">👥 ' + s.top + ' öğrenci katıldı' + (V.durum === 'basladi' ? ' · ' + s.bit + ' teslim' : '') + '</div></div><div class="sag"><div id="osc-pn-yqr"></div><small>ya da karekodu okut</small></div></div><div class="isimler">' + V.katilimcilar.map(function (x) { return '<span>' + esc(x.ad) + '</span>'; }).join('') + '</div>';
      if (window.QRCode) try { new QRCode(document.getElementById('osc-pn-yqr'), { text: V.link, width: 300, height: 300, correctLevel: QRCode.CorrectLevel.M }); } catch (e) {}
    }
    function tikla(e) {
      var b = e.target.closest('[data-k],[data-s]'); if (!b) return;
      if (b.dataset.s) { sekme = b.dataset.s; ciz(); return; }
      var k = b.dataset.k;
      if (k === 'kopyala') { var inp = b.parentNode.querySelector('input'); inp.select(); (navigator.clipboard ? navigator.clipboard.writeText(inp.value) : Promise.reject()).then(function () { bildir('Link kopyalandı', 'ok'); }).catch(function () { document.execCommand('copy'); bildir('Link kopyalandı', 'ok'); }); return; }
      if (k === 'yansit') { yansit = true; yansitCiz(); var z = document.getElementById('osc-pn-yansit'); if (z.requestFullscreen) z.requestFullscreen().catch(function () {}); return; }
      if (k === 'csv') { if (!bitenler().length) return bildir('Henüz teslim eden yok.', 'hata'); csv(); return; }
      if (k === 'yazdir') { if (!bitenler().length) return bildir('Henüz teslim eden yok.', 'hata'); yazdir(); return; }
      if (k === 'sirala') { e.preventDefault(); siralama = b.dataset.v; ciz(); return; }
      var onayMetni = { bitir: V.tur === 'odev' ? 'Ödev kapatılsın mı? Teslim etmeyenlerin kaydedilen cevapları değerlendirilir.' : 'Sınav herkes için bitirilsin mi? Öğrencilerin cevapları otomatik teslim edilir.', sil: 'Oturum ve tüm sonuçları kalıcı olarak silinsin mi?', katilimci_sil: 'Bu öğrenci oturumdan çıkarılsın mı?' }[k];
      if (onayMetni && !confirm(onayMetni)) return;
      b.disabled = true;
      api('komut', { id: id, islem: k, dk: b.dataset.dk, kid: b.dataset.id }).then(function () { if (k === 'sil') { location.hash = ''; return; } if (k === 'baslat') bildir('Sınav başladı!', 'ok'); return yukle(); }).catch(function (er) { b.disabled = false; bildir(er.message, 'hata'); });
    }
    yukle();
    zam = setInterval(function () { if (document.visibilityState === 'visible') yukle(); }, 4000);
  }

  /* ======================= testlerim ======================= */
  var DS = { publish: ['Yayında', 'yesil'], pending: ['Onay bekliyor', 'sari'], draft: ['Taslak', 'gri'] };
  function vTestler() {
    cerceve('test', '<div class="osc-pn-bas"><div><h2 class="osc-pn-h2">Testlerim</h2><p class="osc-pn-not">Hazırladığınız testler yönetici onayından sonra sitede yayınlanır. Onay beklerken de kendi sınıfınızda kullanabilirsiniz.</p></div><a class="osc-pn-btn ana" href="#test/yeni">+ Yeni test</a></div><div id="osc-pn-tl" class="osc-pn-liste"><div class="osc-pn-bos">Yükleniyor…</div></div>');
    api('testlerim').then(function (l) {
      var el = document.getElementById('osc-pn-tl'); if (!el) return;
      if (!l.length) { el.innerHTML = '<div class="osc-pn-bos"><b>Henüz testiniz yok.</b><br><a href="#test/yeni">İlk testinizi hazırlayın →</a></div>'; return; }
      el.innerHTML = l.map(function (t) {
        var d = t.red ? ['Düzeltme istendi', 'kirmizi'] : (DS[t.durum] || ['', '']);
        return '<div class="osc-pn-ok test"><div class="ust"><span class="cip ' + d[1] + '">' + d[0] + '</span><span class="tarih">' + esc(t.tarih) + '</span></div><b>' + esc(t.baslik) + '</b><small>' + t.soru + ' soru · ' + esc(t.tur) + (t.kategori ? ' · ' + esc(t.kategori) : '') + '</small>' + (t.red ? '<div class="red">Yönetici notu: ' + esc(t.red) + '</div>' : '') +
          '<div class="eylem">' + (t.durum !== 'publish' ? '<a class="osc-pn-btn" href="#test/' + t.id + '">Düzenle</a>' : '<a class="osc-pn-btn" href="#test/kopya/' + t.id + '">Kopyala</a>') + '<a class="osc-pn-btn" href="#yeni/canli/' + t.id + '">Sınıfta uygula</a>' + (t.link ? '<a class="osc-pn-btn" target="_blank" href="' + esc(t.link) + '">Sitede gör</a>' : '') + (t.durum !== 'publish' ? '<button class="osc-pn-btn kirmizi-y" data-sil="' + t.id + '">Sil</button>' : '') + '</div></div>';
      }).join('');
      el.querySelectorAll('[data-sil]').forEach(function (b) { b.onclick = function () { if (!confirm('Test silinsin mi?')) return; api('test_sil', { id: b.dataset.sil }).then(function () { bildir('Silindi', 'ok'); vTestler(); }).catch(function (e) { bildir(e.message, 'hata'); }); }; });
    }).catch(function (e) { bildir(e.message, 'hata'); });
  }

  /* ======================= test editörü ======================= */
  function vEditor(id, kopya) {
    var T = { id: 0, baslik: '', aciklama: '', kategori: 0, sinav_turu: '', sure: '', sorular: [] };
    var anahtar = 'osc_pn_taslak_' + (kopya ? 'k' + id : (id || 'yeni'));
    function yeniSoru(tip) { return { type: tip || 'multiple', konu: '', paragraph: '', root: '', options: { A: '', B: '', C: '', D: '', E: '' }, correct: '' }; }
    cerceve('test', '<a href="#testler" class="osc-pn-geri">‹ Testlerim</a><div id="osc-pn-ed"><div class="osc-pn-bos">Yükleniyor…</div></div>');
    var hazir = id ? api('test_al', { id: id }).then(function (t) { T = t; if (kopya) { T.id = 0; T.baslik = T.baslik + ' (kopya)'; } }) : Promise.resolve();
    hazir.then(function () {
      try { var ls = JSON.parse(localStorage.getItem(anahtar) || 'null'); if (ls && ls.sorular && ls.sorular.length && confirm('Bu test için kaydedilmemiş bir taslak bulundu. Kaldığınız yerden devam edilsin mi?')) T = Object.assign(T, ls); } catch (e) {}
      if (!T.sorular.length) T.sorular.push(yeniSoru());
      T.sorular.forEach(function (q) { q.options = q.options || {}; ['A', 'B', 'C', 'D', 'E'].forEach(function (k) { if (q.options[k] === undefined) q.options[k] = ''; }); });
      ciz();
    }).catch(function (e) { bildir(e.message, 'hata'); location.hash = 'testler'; });
    var kayT = null;
    function yerelKaydet() { clearTimeout(kayT); kayT = setTimeout(function () { try { localStorage.setItem(anahtar, JSON.stringify(T)); } catch (e) {} }, 600); }
    function turSecenek() { return '<option value="">Otomatik (başlıktan algıla)</option>' + C.turler.map(function (t) { return '<option value="' + t.k + '"' + (T.sinav_turu === t.k ? ' selected' : '') + '>' + esc(t.ad) + ' — ' + (t.kural ? t.kural + ' yanlış 1 doğru' : 'yanlış götürmez') + '</option>'; }).join(''); }
    function konular() { var l = []; T.sorular.forEach(function (q) { var k = (q.konu || '').trim(); if (k && l.indexOf(k) < 0) l.push(k); }); return l; }
    function araclar() { return '<div class="osc-pn-arac"><button type="button" data-a="b" title="Kalın"><b>K</b></button><button type="button" data-a="i" title="İtalik"><i>İ</i></button><button type="button" data-a="u" title="Altı çizili"><u>A</u></button><button type="button" data-a="sup" title="Üs">x²</button><button type="button" data-a="sub" title="Alt simge">x₂</button><button type="button" data-a="img" title="Görsel ekle">🖼 Görsel</button></div>'; }
    function soruHtml(q, i) {
      var h = '<div class="osc-pn-q" data-i="' + i + '"><div class="osc-pn-q-bas"><span class="no">' + (i + 1) + '</span><select data-f="type"><option value="multiple"' + (q.type === 'multiple' ? ' selected' : '') + '>Çoktan seçmeli</option><option value="truefalse"' + (q.type === 'truefalse' ? ' selected' : '') + '>Doğru / Yanlış</option><option value="gap"' + (q.type === 'gap' ? ' selected' : '') + '>Boşluk doldurma</option><option value="classic"' + (q.type === 'classic' ? ' selected' : '') + '>Açık uçlu (klasik)</option></select>' +
        '<input class="konu" data-f="konu" list="osc-pn-kl" value="' + esc(q.konu) + '" placeholder="Konu (ör. Üslü İfadeler)"><span class="bosluk"></span><button type="button" data-q="yukari" title="Yukarı">↑</button><button type="button" data-q="asagi" title="Aşağı">↓</button><button type="button" data-q="kopya" title="Çoğalt">⧉</button><button type="button" data-q="sil" class="sil" title="Sil">🗑</button></div>';
      h += '<div class="osc-pn-alan' + (q.paragraph ? '' : ' kapali') + '"><label>Paragraf / öncül <small>(isteğe bağlı)</small></label>' + araclar() + '<div class="osc-pn-ce" contenteditable="true" data-f="paragraph" data-ph="Okuma parçası, tablo açıklaması ya da öncüller…">' + (q.paragraph || '') + '</div></div>' + (q.paragraph ? '' : '<button type="button" class="osc-pn-link" data-q="para">+ Paragraf / öncül ekle</button>');
      h += '<div class="osc-pn-alan"><label>Soru kökü</label>' + araclar() + '<div class="osc-pn-ce kok" contenteditable="true" data-f="root" data-ph="Soruyu yazın. Görseli yapıştırabilir ya da 🖼 ile ekleyebilirsiniz.">' + (q.root || '') + '</div></div>';
      if (q.type === 'multiple') {
        h += '<div class="osc-pn-siklar"><label>Şıklar <small>— doğru şıkkın harfine tıklayın</small></label>' + ['A', 'B', 'C', 'D', 'E'].map(function (k) { return '<div class="osc-pn-sik' + (q.correct === k ? ' dogru' : '') + '"><button type="button" class="harf" data-dogru="' + k + '" title="Doğru cevap olarak işaretle">' + k + '</button><div class="osc-pn-ce tek" contenteditable="true" data-o="' + k + '" data-ph="' + (k === 'E' ? 'E şıkkı (LGS gibi 4 şıklı testlerde boş bırakın)' : k + ' şıkkı') + '">' + (q.options[k] || '') + '</div>' + (q.correct === k ? '<span class="tik">✓ Doğru</span>' : '') + '</div>'; }).join('') + '</div>';
      } else if (q.type === 'truefalse') {
        h += '<div class="osc-pn-dy"><label>Doğru cevap</label><button type="button" data-dogru="A" class="' + (q.correct === 'A' ? 'on' : '') + '">✓ Doğru</button><button type="button" data-dogru="B" class="' + (q.correct === 'B' ? 'on' : '') + '">✗ Yanlış</button></div>';
      } else {
        h += '<div class="osc-pn-alan"><label>' + (q.type === 'gap' ? 'Doğru cevap <small>(alternatifleri / ile ayırın: Ankara / Angora)</small>' : 'Model cevap <small>(öğrencinin cevabı bununla karşılaştırılır)</small>') + '</label><div class="osc-pn-ce' + (q.type === 'gap' ? ' tek' : '') + '" contenteditable="true" data-o="A" data-ph="Cevap">' + (q.options.A || '') + '</div></div>';
      }
      return h + '</div>';
    }
    function ciz() {
      var el = document.getElementById('osc-pn-ed'); if (!el) return;
      el.innerHTML = '<div class="osc-pn-kart"><h3>' + (T.id ? 'Testi düzenle' : 'Yeni test') + '</h3><div class="osc-pn-iz">' +
        '<label class="genis">Test başlığı<input data-t="baslik" value="' + esc(T.baslik) + '" placeholder="Örn: 8. Sınıf LGS Matematik – Üslü İfadeler Testi"></label>' +
        '<label>Kategori<select data-t="kategori"><option value="0">Seçin…</option>' + C.kategoriler.map(function (c) { return '<option value="' + c.id + '"' + (+T.kategori === c.id ? ' selected' : '') + '>' + esc(c.ad) + '</option>'; }).join('') + '</select></label>' +
        '<label>Sınav türü (net hesabı)<select data-t="sinav_turu">' + turSecenek() + '</select></label>' +
        '<label>Süre (dakika)<input data-t="sure" type="number" min="0" max="600" value="' + esc(T.sure) + '" placeholder="Boş: sınav türüne göre"></label>' +
        '<label class="genis">Kısa açıklama <small>(sitede testin üstünde görünür)</small><textarea data-t="aciklama" rows="2" placeholder="Bu test … konularını kapsar.">' + esc(T.aciklama) + '</textarea></label></div>' +
        '<div class="osc-pn-dosya-k"><div class="ik">📄</div><div class="ac"><b>Dosyadan soru al</b><small>PDF, Word (.docx), metin ya da soru fotoğrafı (PNG/JPG) yükleyin; sorular, şıklar, görseller ve cevap anahtarı otomatik okunur.</small><span id="osc-pn-dosya-durum"></span></div><button type="button" class="osc-pn-btn ana" data-e="dosya">Dosya seç</button><input type="file" id="osc-pn-ice" accept=".pdf,.docx,.txt,image/*" hidden></div>' +
        '<div class="osc-pn-hizli"><div><b>Cevap anahtarını hızlı gir</b><small>Çoktan seçmeli soruların doğru şıklarını sırayla yazın: <code>ABDCA BCD…</code></small></div><input id="osc-pn-anahtar" placeholder="Örn: ABCDA BCDAB" autocomplete="off"><button type="button" class="osc-pn-btn" data-e="anahtar">Uygula</button></div></div>' +
        '<datalist id="osc-pn-kl">' + konular().map(function (k) { return '<option value="' + esc(k) + '">'; }).join('') + '</datalist>' +
