      anahtar.split('\n').forEach(function (l) { var m = l.match(/^\s*(?:soru\s*)?(\d{1,2})\s*[\)\.\-–:]\s*(.{2,})$/i); if (m && !/^[A-Ea-e](\s|$|[,;])/.test(m[2])) ak[+m[1]] = m[2].trim(); });
    }
    return sorular.map(function (q) {
