      }).then(function () { if (no !== kuyrukNo) return; sakla(); if (--kalan === 0 && hata) bildir(hata + ' Boş kalan soruları “Değiştir” ile yeniden deneyebilir ya da kendiniz yazabilirsiniz.', 'uyari'); calis(); });
